INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M04XYEFE9BKW5TV9701GKQVF', '01M04XXNBGJS968318HYM0WAM8', 'Reach for it before assuming the surface has it', '**Source**: retro 38, Codebase Discoveries — "The surface refuses what it never anticipated, and refuses it quietly." `entityTools` dropped nulls, so a waiver could not be lifted and the refused clear reported success. `list_artifact_document` was scoped one way only. `artifact.url` and `published_at` are both `NOT NULL`. `review_agent` is kind-pinned to `review`. `document_kind` was neither readable nor listable. The shared `Perspectives` procedure loaded a roster without `include_body` and rendered voices off nothing.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M04XYS90T01YE3QY0GWN8AKA', '01M04XXNBGJS968318HYM0WAM8', 'A check that passes may be passing for a reason other than the one you want', '**Sources**: retro 42, Criteria gaps; retro 56, Testing gaps. Promoted because it is the single most re-derived lesson in this project''s history — the same rule was found independently, in a different disguise, in **thirteen** retros: 35 (a truncated check reported a pass it never computed), 36 (a green suite proved nothing about whether the server could start; section-scoped assertions alias against nearby prose), 37 (two checks that agree are not two checks), 38 (three quantifier failures, all making the assertion vacuous rather than wrong), 39 (a green assertion is not evidence until the wrong answer is known to be excluded), 40 (a vacuous regex reads exactly like a working one), 41 (a criterion phrased as "the corpus still has N of these" expires the moment the epic succeeds), 42, 44 (a specific assertion placed behind a generic one never runs), 45 (a criterion with two failure shapes gets tested against whichever one the code makes easy), 47 (a token sweep cannot prove a path writes nothing), 49 (a comparator that never sorts passes an ordering test whose code already emits in order), and 56.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M04XZ45N7MTCBF1GX9X68YD9', '01M04XXNBGJS968318HYM0WAM8', 'A control mutation needs a revert that cannot take the tree with it', '**Source**: retro 56, Testing gaps.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M04Y2PYPSJ8P96G8J9AGCV1W', '01M04XXNBGJS968318HYM0WAM8', 'A control is only a control once you have watched it fail, and read why', '**Synthesised from** retros 37, 39, 44, 46, 47, 48 and 55 — the second theme this project re-derived repeatedly. Unlike the entries above this is a synthesis rather than the promotion of one observation, so those retros keep their originals rather than carrying a retirement marker.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M050NPBGJPF3DGFC5CNCA9CK', '01M050N7S7YF827QD2CH0TVTFK', 'Problem recap', 'An MCP server is pinned to a version directory for the life of the session. The plugin root is resolved once at launch; installing a new plugin version writes a new version directory and repoints the installation registry, and reaches into nothing already running. Only sessions open *across* an upgrade are affected, and nothing tells them.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M051QZ3KAQR98TTAZRKX0PJJ', '01M050N7S7YF827QD2CH0TVTFK', 'In scope', 'The neighbour check, taking the plugin root as an argument rather than reading it from the environment, evaluated each time it is reported.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M051R4NVP2WQ98AR8A1QQ8R3', '01M050N7S7YF827QD2CH0TVTFK', 'Out of scope', 'The three excluded requirements carry their reasoning on their own rows: refusing or degrading tool calls on a backward skew, self-repairing by loading from a newer sibling directory, and restarting the server into the newer version.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M051R9S9BMV48YK5194EWBGH', '01M050N7S7YF827QD2CH0TVTFK', 'Deferred', '**Consulting the host''s installation registry** (FR8), which would still detect a skew once the older sibling directories have been swept. Deferred rather than excluded: the decision records it as the route this takes when the sibling scan proves insufficient.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M052788NATYB2CQ5QHJ68EQS', '01M050N7S7YF827QD2CH0TVTFK', 'Integration boundaries', 'Five seams, drawn from the decisions rather than invented.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M054JSTAKYNJQWKDH2TP8P1A', '01M052GWNT4AY7KXAR34WVS29E', 'Amendment: story 1''s fixture criterion no longer waits on story 3', 'Story 1''s first criterion read "A constructed directory of sibling version directories exists in the suite, **and the check reports a verdict against it**". The second clause names an artefact story 1 cannot have.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M05HXZG40HF08ABQV9M8QTKG', '01M05HXF3GS1DSX68YSBR6M0C8', 'What was actually different', 'The consultation started from an observation — that the two boards feel different — and was answered by reading both trees, `cpm/tools/board/` and `dpm/tools/board/`, rather than from memory. Four differences are real, and they are not all of the same kind.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M05HYKM0A3EHHFEJHK7TN500', '01M05HXF3GS1DSX68YSBR6M0C8', 'What was decided, and why', '**CPM''s keys are the base; DPM''s extra capabilities take non-colliding keys.** The alternative on the table was literal parity — every shared key identical and everything DPM-only pushed into the command palette — and it was rejected because search and coverage gaps are the things a user opens the DPM board to do, and a palette-only capability costs two keystrokes forever. The rule chosen keeps muscle memory intact where the two boards do the same thing and spends new keyspace only where DPM does something CPM cannot.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M05HYZ3YA7W4XQC0BY4YEA0Q', '01M05HXF3GS1DSX68YSBR6M0C8', 'Open when it ended', 'The consultation closed on the scope being agreed in outline rather than on it being complete, and three things were never settled.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M05J87D25PHGZJVMG97PVCBJ', '01M05J7VD7PWH32KWMND9MGHMN', 'Problem recap', 'The DPM board and the CPM board were built to the same shape and have drifted apart. A user moving between them finds the keys mean different things, the highlighted row looks different, and the panel beneath a column shows raw markdown on one board and rendered markdown on the other. Four differences are established, from reading both trees rather than from recollection.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M05KVCRGZPGN0BX7AC69DNYY', '01M05J7VD7PWH32KWMND9MGHMN', 'Scope boundary', '**In scope.** The key rebinds and the new hide-retired behaviour (FR1–FR3); the cursor and pill ports (FR4, FR5); markdown previews and the re-cut preview builders (FR6, FR6a); footer labels and palette entries for the keys that moved (FR7); the surface-by-surface comparison of the two boards (FR8); and the cross-board parity test (FR9, per AD2). Moving the tests that pin what changes is part of the work rather than a consequence of it — `test_previews.py` asserts the current plain-text preview shapes, and anything asserting today''s key map moves with FR1.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M05MJD576AP6NPJFSAJF4YKD', '01M05J7VD7PWH32KWMND9MGHMN', 'Integration boundaries', 'Four seams, each following from a decision in Section 4, and each the place integration coverage belongs rather than unit coverage.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M05TM7RYC9VW0K0SX5M8HPKG', '01M05NNYYBX6XYRMND1CN4M4TY', 'The host''s Python floor, and why this run left it unverified', 'Story 2''s sixth criterion — the host running the board has Python 3.11 or later, and `uv run` provisions the board from its inline block there — carries `target` and nothing else, so this run did not assess it and did not count it met. Confirming a floor of 3.11 on a machine running 3.11 is precisely the false pass the tag exists to stop, and no verdict from a development machine is worth anything about a host nobody here has.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M05XF25BRPCQMN8YPR9WKSP8', '01M05NNZQE4VVEWMCXGMZ72YJ5', 'The three interaction surfaces, and what each comparison found', 'Story 6''s sweep. Three surfaces were compared against `cpm/tools/board/board.py` in this checkout, and each has an outcome below — a difference closed, a difference recorded as deliberate, or a statement that the surface agrees. None is left without one, because a surface nobody compared reads afterwards exactly like one that was compared and agreed.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M05XJRWF9R2TM5CF1XQVBN95', '01M05NNZQE4VVEWMCXGMZ72YJ5', 'FR9 is verified in one direction and left unclaimed', 'Every coverage row under FR9 is verified and the requirement is deliberately not claimed, which is a distinction worth stating rather than leaving to be inferred from an empty field.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M060BWNYKVGA5YJD3EH94YXN', '01M05NP14C3GCH372FM6NN2T5S', 'What this epic left unclaimed, and why', 'Three of the four requirements this epic delivers against are left without a coverage claim. Every coverage row under them is verified; what is missing in each case is an obligation in the requirement''s own sentence that no bound fragment reaches, and a claim is a judgement rather than a sum of rows.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M061CGSF5ACP40HN22SRHMXF', '01M05NP15VPTJKBNK0B2HQ4XCZ', 'A criterion added to story 2, and what it closes', 'Story 2 gained a sixth criterion during the run: *"A preview the raster produced reaches a terminal reporting 256 colours as 8-bit colour and no 24-bit codes, so no colour system named where the terminal cannot be seen decides whether a preview is legible."* It is tagged `unit`, covered by `tests/test_raster.py`, and bound to NFR3 and ENVX4.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M061WH62PSPBB5PZKT1VBMH5', '01M05NP15VPTJKBNK0B2HQ4XCZ', 'Story 4''s control, amended: no input takes the renderer down', 'Story 4''s control criterion read: *"With the guard removed, the same input takes the board down — so the criterion above cannot pass against a renderer that was never at risk from it."* It cannot be satisfied as written, and the citation is the renderer''s own behaviour.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M062ECG5NPD6HP4JZZBFZQHR', '01M05NP15VPTJKBNK0B2HQ4XCZ', 'Surface sweep 1 — column layout', 'Compared against `cpm/tools/board/board.py`''s `compose` and CSS, from the repository source of both boards.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M062EQ6XEDT3YAFRQB89PS0X', '01M05NP15VPTJKBNK0B2HQ4XCZ', 'Surface sweep 2 — row composition', 'Compared against `cpm/tools/board/board_view.py`''s `project_label`, `project_row_text` and the epic-row builders.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M062F2G59SHNTF6QWVAM2KW8', '01M05NP15VPTJKBNK0B2HQ4XCZ', 'Surface sweep 3 — CSS', 'Compared rule by rule against the CPM board''s `CSS` block.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M062FGCERK4M827DN46DFB2V', '01M05NP15VPTJKBNK0B2HQ4XCZ', 'Surface sweep 4 — preview behaviour', 'The surface this epic moved, so the comparison is against what stories 1 to 4 left behind rather than against what was there in the morning.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M0659QZJZJWBP5YFT04KDCWK', '01M0659D8ZXWYSFXE6M8ZM3CM2', 'What is wrong', '`check_integrity` on this project''s own database returns `ok: false` on entry 6 — *"A dependency''s ends are kinds that edge admits"* — naming edge `01M05J88V2WYQPDEFCZJM1G89J`, a `builds_on` from spec 2 to discussion 1.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M065A35HCQD0XCW2NR1MA63A', '01M0659D8ZXWYSFXE6M8ZM3CM2', 'Why it is not simply a widened WHERE clause', 'The register states its own reasoning at `dpm/src/integrity/register.js:24-29`, and it argues against the quick fix:
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M066AZWPEVX0D49ER8C0BJ48', '01M0659D8ZXWYSFXE6M8ZM3CM2', 'What changed', 'Resolution 2 of the three: the pairs are rows, and both the write and the audit read them.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M066BD3BBXPH5R6JD1Q3482W', '01M0659D8ZXWYSFXE6M8ZM3CM2', 'How it was verified, and what the migration costs the reader', '**818 tests, 817 passing before this project''s own database was brought up, 818 after.** Six of them are new, in `tests/dependency-endpoints.test.js`.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M0Z04X38ASC0AFW8MV6F3HMJ', '01M0Z04X2W3E7M5T9W6VJRR6KB', 'The change', 'DPM 0.4.0 gave every report a disposition: each item a run mentions carries one of Fixed, Left alone, Unverified or Needs you, named for what the *reader* must do rather than for what the run did. CPM had no equivalent, so a CPM skill''s closing summary was prose whose actionable item had to be found by reading all of it. This ports the convention.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M0Z04X3BF0ZQRF455ATCNXQT', '01M0Z04X2W3E7M5T9W6VJRR6KB', 'Files affected', '- `cpm/shared/skill-conventions.md` — new `## Disposition` section after `## Conversational Output`.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M0Z04X3DB0D817995EHBT3HY', '01M0Z04X2W3E7M5T9W6VJRR6KB', 'What changed', 'The shared file gained the four dispositions and the four rules that make them mean anything, plus a fifth that is CPM''s own: a skill names its own items and does not restate the definitions, which is the job DPM''s `list_taxonomy` call does there.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M0Z04X3FH49KH19KBXVTQQX7', '01M0Z04X2W3E7M5T9W6VJRR6KB', 'How it was verified', '`bash cpm/hooks/tests/test-disposition-convention.sh` — 23 assertions in 23 tests, all passing. Five are controls, and they are the ones worth naming. A slice-width control fails if the awk range swallows the rest of the file. A non-empty control on the label extractor fails if the bullet format changes, which would otherwise compare empty against empty and report green. An emission control asserts the extract carries a core section''s body, without which "the Disposition body is absent" is satisfied by an emitter that produced nothing. And two negative controls: `brief` must not reference the convention, and no skill may reproduce three or more of the four definitions in place of naming its own items.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M0Z05YZ4QER1YNW1ASPG32VE', '01M0Z05YYS3TW9P6GF4D5E29NT', 'The change', '`dpm-import.js` refused to rebuild this project''s database, reporting that the dump did not survive its own restore. It was right to.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M0Z05YZ58BR0AD0C664QAFMG', '01M0Z05YYS3TW9P6GF4D5E29NT', 'Files affected', '- `dpm/src/dump/objects.js` — new `maintainsVirtualTable` predicate, matching on the trigger''s body rather than its name.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M0Z05YZ67XQWVMB93PJKKBEY', '01M0Z05YYS3TW9P6GF4D5E29NT', 'How it was found', 'Not by the suite. 818 tests passed over the defect, and the existing assertion that a refused rebuild leaves the database unreplaced cannot see it either — its before and after are indistinguishable by the slugs it compares.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M0Z0GPCNP3DYA8M0WHMH9XRM', '01M0Z0GPCB1JYVZRWWRC88Z880', 'The change', '`rebuild` restored into a staging database, renamed it into place, and only then asked whether the dump survived its own restore. So the refusal — "committing it would commit a state nobody reviewed" — was issued about a state that was already the database. Observed doing exactly that: an import refused, having first replaced a one-document database with a twenty-seven-document one.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M0Z0GPCQDEQ9KFRFEDCJRYZE', '01M0Z0GPCB1JYVZRWWRC88Z880', 'Files affected', '- `dpm/src/rebuild/index.js` — the round-trip check moved inside the staging block; the catch re-throws a `RebuildError` unwrapped so a refusal keeps its own words.
INSERT INTO "document_section" ("id", "document_id", "heading", "body", "position", "superseded_at") VALUES ('01M0Z0GPCQDEQ9KFRFEDCJRYZF', '01M0Z0GPCB1JYVZRWWRC88Z880', 'How it was found', 'Not by the suite, and not by inspection. The assertion for this exact property has been in `rebuild.test.js` since epic 49-04 and passed throughout, because its two states were indistinguishable by the slugs it compared: the fixture built the refused dump by editing the dump the database had been restored from, so both sides read `[already-here]` whether or not the replacement happened.
INSERT INTO "library_document" ("document_id", "document_kind", "doc_type", "source") VALUES ('01M04XXNBGJS968318HYM0WAM8', 'library', 'coding-standards', 'docs/cpm/library/lessons-learned.md — carried over from CPM at the 2026-08-16 migration, with its amendment blocks folded into the body');
INSERT INTO "library_scope" ("document_id", "scope") VALUES ('01M04XXNBGJS968318HYM0WAM8', 'do');
INSERT INTO "adr" ("document_id", "document_kind", "decision_status", "decision") VALUES ('01M051JPHA56Z9A2VTMBV2EWHY', 'adr', 'accepted', 'A skew is reported in a new top-level field of `check_integrity`''s response, separate from `entries` and `orphans` and carrying its own verdict and could-not-check state, leaving `ok` a statement about the data alone.');
INSERT INTO "adr" ("document_id", "document_kind", "decision_status", "decision") VALUES ('01M051JRSZA8SNR8N4NXQRQ0ZY', 'adr', 'accepted', 'The plugin version is recorded in a new one-row table introduced by a migration, accepting the one-time consequence that servers older than that release degrade to read-only against any project the new release has opened.');
INSERT INTO "adr" ("document_id", "document_kind", "decision_status", "decision") VALUES ('01M051JTJK59ZEVNHVWNJM286Q', 'adr', 'accepted', 'The running plugin''s directory is derived from the module''s own URL and its siblings are read from the parent directory and compared as versions with the existing `parseVersion`, with the root taken as an argument rather than from the environment.');
INSERT INTO "adr" ("document_id", "document_kind", "decision_status", "decision") VALUES ('01M05KKC6ZMQ52YFG1RYC56E8J', 'adr', 'accepted', 'The cursor and markdown rendering are copied into the DPM board''s own `board.py`, and the copy is kept honest by the cross-board check of AD2 rather than by a shared artefact.');
INSERT INTO "adr" ("document_id", "document_kind", "decision_status", "decision") VALUES ('01M05KKE8HPZVWEGD8YPVFS4E8', 'adr', 'accepted', 'A test in the DPM board''s suite reads the CPM board''s source and asserts that every key CPM binds carries the same meaning on DPM, treating an unreadable CPM tree as a failure rather than a skip.');
INSERT INTO "adr" ("document_id", "document_kind", "decision_status", "decision") VALUES ('01M05KKFSN1V96DAPTMHDAGMKT', 'adr', 'accepted', '`board_view.py`''s preview builders emit markdown source and stay free of Textual and Rich; the rasteriser that turns it into a renderable lives in `board.py` with the widgets.');
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M051K1KHBMJJX6VTF1F2TXAZ', '01M051JPHA56Z9A2VTMBV2EWHY', 'A new top-level field', 1, 'The skew sits beside `entries` and `orphans` rather than inside either, with its own verdict and its own could-not-check state. `ok` continues to mean the database is internally consistent, which it is — the rows are sound and the reader is stale. The field is present whether or not a skew was found, because an absent field and a field reporting nothing found read identically to someone who was not already looking for it.', 0);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M051K3WPAVHV481KMPD62QW4', '01M051JPHA56Z9A2VTMBV2EWHY', 'A register entry', 0, 'Rejected. `entries` is built by mapping over the register so that an entry added there appears in the report without the tool being edited, and a parity test holds that derivation. A version skew names no rows and is not a cross-row invariant, so it would have to arrive either as a fake register entry or by breaking the mapping — and the second would cost the property the parity test exists to protect.', 1);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M051K6SRPA4CZ2J3SB07JEZM', '01M051JPHA56Z9A2VTMBV2EWHY', 'Setting `ok` to false', 0, 'Rejected. It would guarantee the warning is noticed, at the price of the report saying the database is broken when nothing is wrong with it. Every caller branching on `ok` would begin treating an environment warning as corruption, and the one report whose job is to be trusted would start crying wolf.', 2);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M051KAAEKYJNBV8STXF1S9Y7', '01M051JRSZA8SNR8N4NXQRQ0ZY', 'A new one-row table', 1, 'A named table holding a named column, arriving through the migration path everything else in the schema arrives through, and appearing in the dump like every other row. It costs a schema bump, and therefore costs older servers their write tools against any project this release has opened. That is accepted: read-only is already the policy for a database a server does not fully understand, so this extends an existing rule by one release rather than inventing a lockout. The cost is also one-time and bounded — the stamp records the plugin version rather than the schema version, so every release after it moves the stamp without moving the schema.', 0);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M051KDP8VDCSFBJ7BCQYXPVK', '01M051JRSZA8SNR8N4NXQRQ0ZY', 'A column on `schema_version`', 0, 'Rejected. It costs the same schema bump as its own table while additionally putting two adjacent answers in one place: `schema_version` records how far the database has been migrated, one row per migration, and the plugin version is neither of those things. A table holding one fact per row and another fact on some of those rows is a table that will be read wrongly.', 1);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M051KGCK9HG6ASNKPGQ3ZA21', '01M051JRSZA8SNR8N4NXQRQ0ZY', '`PRAGMA user_version`', 0, 'Rejected, and it is the one that tempts. It avoids the migration and the bump entirely. But it is a single unnamed 32-bit integer, so a three-part version has to be encoded into it and decoded on the way out, and the slot belongs to whoever claims it first — nothing marks it as ours, and nothing would notice if something else began writing there.', 2);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M051KK0AEXHQ7P9118CQP1PP', '01M051JRSZA8SNR8N4NXQRQ0ZY', 'A sidecar file beside the database', 0, 'Rejected. It avoids the schema bump, and it is a file rather than a row in a system whose thesis is that planning state is rows and files are a generated projection. To be useful across a team it would have to be committed, which means the pre-commit guard has to learn about it, which means a second artefact to keep in step with the database — more machinery than the migration it was avoiding.', 3);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M051KNWC8HBWK4HHPASBABDF', '01M051JTJK59ZEVNHVWNJM286Q', 'Sibling directory scan', 1, 'The running directory comes from the module''s own URL, the parent is read, and the names are compared as versions with the parser the Node floor check already uses. It depends on one property of the host — that versions are sibling directories — rather than on a file format. The root is a parameter, which is what makes it testable against a constructed directory instead of against the author''s own machine.', 0);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M051KSV79WJZXMVZ1PY79ESW', '01M051JTJK59ZEVNHVWNJM286Q', 'Read the host''s installation registry', 0, 'Not chosen now, and the route FR8 would take. It carries strictly better information — which version is current, rather than which are present — and would still detect a skew after the older sibling directories are swept. It is rejected for the first release because it is an undocumented JSON file at a path we would have to construct, owned by a component shipping on its own schedule. A weaker signal from a stabler surface is the better first move.', 1);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M051KVG2NWPTJTFC8S7DV0F8', '01M051JTJK59ZEVNHVWNJM286Q', 'Query the marketplace over the network', 0, 'Rejected, and foreclosed by ENVX4. It answers a different question — what has been published, rather than what is installed — and makes a local diagnostic fail differently depending on whether the machine is online.', 2);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M05KKP0WZ9X2QXE7GBD3C8DV', '01M05KKC6ZMQ52YFG1RYC56E8J', 'Copy into the DPM board', 1, 'Each board stays a self-provisioning single-file script, which is what FR11 preserves and what lets either be run straight from a plugin cache with no install step. The cost — a third copy of a rendering idea, and copies drift — is exactly the defect this spec repairs, so the copy is accepted only because AD2 puts a mechanical check under it.', 0);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M05KKSFH4XQ9AMEZMYZJKNBC', '01M05KKC6ZMQ52YFG1RYC56E8J', 'A vendored file kept in step by a sync script', 0, 'Makes the duplication explicit and mechanical rather than hand-made. Rejected because it adds a build step to two plugins that currently have none, and the script is itself a thing that can be forgotten — it converts "did anyone copy the change across" into "did anyone run the script", which is the same question wearing different clothes.', 1);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M05KKVHCD2KCTRSXSZ0HBCG9', '01M05KKC6ZMQ52YFG1RYC56E8J', 'A shared installable package', 0, 'The structurally correct answer to duplication, and ruled out by FR11 rather than on its merits: it would give both boards a dependency neither can satisfy from a PEP 723 inline block, and end the property that a board is one file you can run.', 2);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M05KKZNM8SVJB23W2KZGDFV8', '01M05KKE8HPZVWEGD8YPVFS4E8', 'Cross-board test, absent tree is a failure', 1, 'ENV4 states the CPM tree is readable where development happens, so a checkout without it is a broken environment rather than an excused one, and saying so out loud is the difference between a check and a check-shaped thing. What it asserts is stated over the category rather than as an equality: every key CPM binds means the same on DPM, DPM''s extra keys touch nothing in that set. An equality over the whole map would fire the first time either board legitimately grows a key — the shape retro 1 named as a change detector wearing a rejection''s clothes.', 0);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M05KM2DWG0EFTG1NVMASKMPA', '01M05KKE8HPZVWEGD8YPVFS4E8', 'Cross-board test that skips when the tree is absent', 0, 'Runs anywhere, which is the whole of its appeal. Rejected because a test that stops checking without saying so is worse than no test: the green run afterwards means something different from the green run before it, and nothing in the output distinguishes them. This project has already been bitten by a check that passed while exercising a short circuit.', 1);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M05KM564VTPPP2ZQJWWCQNPV', '01M05KKE8HPZVWEGD8YPVFS4E8', 'A key-map fixture checked into each tree', 0, 'Each suite asserts its own board against its own fixture, with no suite reaching sideways. Rejected because nothing then compares the two fixtures with each other: it detects a board drifting from its own declaration and is blind to the two declarations drifting apart, which is the failure actually being guarded against.', 2);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M05KM81FJA4E7G5581AWSXRM', '01M05KKE8HPZVWEGD8YPVFS4E8', 'A maintenance record and no test', 0, 'Cheapest, and honest about being a note rather than a check. Rejected because the drift this spec repairs happened under exactly these conditions — two boards, no check, and no record either. Retro 1 also found that a warning written in one file did not prevent a second occurrence in another, because a warning is only read where the reader already is.', 3);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M05KMARFQVGJ4770HTT9RN2S', '01M05KKFSN1V96DAPTMHDAGMKT', 'Builders emit markdown source; board.py rasterises', 1, 'Keeps `board_view.py` free of Textual and Rich, which is what makes its existing tests plain string assertions, and confines the width-specific, resize-driven work to the module that owns the widgets. The preview tests stay what they are — markdown source is still a string — and the raster gets tests of its own about width and selection.', 0);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M05KMCVH924BJXQJTESXQVSC', '01M05KKFSN1V96DAPTMHDAGMKT', 'Rasterise inside board_view', 0, 'One module would own the whole preview path. Rejected because it pulls Rich into the only module in the board that has no rendering dependency, and turns every preview assertion into a rendering assertion — a test about which criteria appear would then fail when a heading style changed.', 1);
INSERT INTO "adr_option" ("id", "adr_id", "name", "chosen", "rationale", "position") VALUES ('01M05KMF2EVDD60XMFSSTVJ2SY', '01M05KKFSN1V96DAPTMHDAGMKT', 'Builders return structured objects', 0, 'Typed preview objects formatted by `board.py`. Rejected as a layer bought for nothing: markdown is already the interchange format both boards use, the CPM renderer takes a string, and the structure would exist solely to be flattened into one on the other side of the boundary.', 2);
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M051K1KHBMJJX6VTF1F2TXAZ', 'complexity', 'Low, but it introduces a second notion of "something is wrong" alongside `ok`. Anyone reading the report now has two places to look, and the field has to be self-describing enough that the second place is obvious.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M051K1KHBMJJX6VTF1F2TXAZ', 'cost', 'One added field on one response. Nothing existing changes shape, so no caller of `check_integrity` has to be touched.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M051K1KHBMJJX6VTF1F2TXAZ', 'reversibility', 'High. An added field can be renamed or moved while `ok` and `entries` keep their meanings, because nothing downstream has been asked to reinterpret what it already reads.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M051K6SRPA4CZ2J3SB07JEZM', 'reversibility', 'Low, and that is the reason to refuse it rather than try it. Once `ok` has meant "no skew either" for one release, every caller written against it encodes that meaning, and narrowing it back is a silent behaviour change in the direction of missing things.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M051KAAEKYJNBV8STXF1S9Y7', 'complexity', 'Low, and deliberately the most boring option available. It uses the migration path, the dump and the guard exactly as they already work, so nothing new has to be kept in step.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M051KAAEKYJNBV8STXF1S9Y7', 'cost', 'A migration file, a table, and a one-time read-only lockout for anyone still on an older plugin the first time this release opens a shared project. The lockout is the real price and it is paid by people who did nothing.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M051KAAEKYJNBV8STXF1S9Y7', 'reversibility', 'Low in one direction only. A schema version, once raised, cannot be lowered for databases already migrated, so the lockout cannot be taken back by a later release. What can be changed freely is what is done with the stamp — the reading, the comparison and the reporting are all ordinary code.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M051KGCK9HG6ASNKPGQ3ZA21', 'cost', 'Lowest of the four up front — no migration, no bump, no lockout, and no change to the dump''s shape.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M051KGCK9HG6ASNKPGQ3ZA21', 'reversibility', 'Superficially high and actually poor. Moving off the pragma later means every database already carrying an encoded integer has to be read by something that knows the encoding, and by then the encoding is undocumented history rather than a decision.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M051KK0AEXHQ7P9118CQP1PP', 'complexity', 'Highest of the four, in the place it is least visible. A committed sidecar becomes a second artefact the pre-commit guard has to reconcile, which is the machinery the migration was supposedly too expensive for.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M051KNWC8HBWK4HHPASBABDF', 'complexity', 'Low in code and non-zero in coupling: it assumes the host lays versions out as sibling directories. That assumption is the thing recorded in the maintenance record under NFR5, because it is the host''s to change.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M051KNWC8HBWK4HHPASBABDF', 'cost', 'One directory read and a comparison, reusing a parser that already exists. No dependency, no schema change, no new file.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M051KNWC8HBWK4HHPASBABDF', 'reversibility', 'High. It writes nothing and nothing persists, so it can be replaced or removed in a release without leaving anything behind to migrate.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M051KSV79WJZXMVZ1PY79ESW', 'reversibility', 'High, which is why deferring it costs nothing. It reads a file and persists no state, so adopting it under FR8 later is an addition rather than a migration away from this.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M05KKP0WZ9X2QXE7GBD3C8DV', 'cost', 'Low to apply and permanent to carry: the port is one afternoon, and the duplication is paid at every future change to either renderer.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M05KKP0WZ9X2QXE7GBD3C8DV', 'reversibility', 'Fully reversible. Extracting a shared module later is strictly easier from two copies that are known to agree than from two that have drifted.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M05KKSFH4XQ9AMEZMYZJKNBC', 'complexity', 'Adds a build step to two plugins that have none, and a script whose being run is itself unchecked.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M05KKZNM8SVJB23W2KZGDFV8', 'complexity', 'Couples the DPM board''s suite to the CPM tree''s path, which ENV4 states and ENVX3 confines to development. The board itself gains no such reach.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M05KKZNM8SVJB23W2KZGDFV8', 'cost', 'One test in one suite. The work is in stating the assertion over the category rather than as an equality, not in reaching the other tree.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M05KM2DWG0EFTG1NVMASKMPA', 'reversibility', 'Easy to change later and hard to notice needing it: a skipped check reports the same green as a passing one.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M05KMARFQVGJ4770HTT9RN2S', 'complexity', 'Holds the existing module boundary rather than moving it. The one new concept is that a preview builder''s output is markdown, which is what FR6a states.');
INSERT INTO "adr_option_tradeoff" ("option_id", "axis", "assessment") VALUES ('01M05KMARFQVGJ4770HTT9RN2S', 'cost', 'The existing preview tests move rather than being rewritten — they assert on strings before and after.');
INSERT INTO "quick" ("document_id", "document_kind", "closed_at") VALUES ('01M0659D8ZXWYSFXE6M8ZM3CM2', 'quick', '2026-08-16T21:10:00Z');
INSERT INTO "quick" ("document_id", "document_kind", "closed_at") VALUES ('01M0Z04X2W3E7M5T9W6VJRR6KB', 'quick', '2026-08-26T11:50:00.000Z');
INSERT INTO "quick" ("document_id", "document_kind", "closed_at") VALUES ('01M0Z05YYS3TW9P6GF4D5E29NT', 'quick', '2026-08-26T13:30:00.000Z');
INSERT INTO "quick" ("document_id", "document_kind", "closed_at") VALUES ('01M0Z0GPCB1JYVZRWWRC88Z880', 'quick', '2026-08-26T14:10:00.000Z');
INSERT INTO "quick_criterion" ("id", "quick_id", "text", "met", "note", "position") VALUES ('01M065A6R98HEFWKCHBPWA8RJ6', '01M0659D8ZXWYSFXE6M8ZM3CM2', '`check_integrity` on this project''s own database returns `ok: true`, with entry 6 held and no row reported.', 1, 'Verified against a copy of this project''s own `.dpm/dpm.db`, migrated to schema 24 by the new code: all thirteen register entries hold, and entry 6 returns no rows where it previously named edge 01M05J88V2WYQPDEFCZJM1G89J. The MCP server running in the session that made this change is the installed 0.5.0, whose schema target is 23, so its own `check_integrity` answers for a database it has not migrated — hence the copy, which is the same rows against the code under test.', 0);
INSERT INTO "quick_criterion" ("id", "quick_id", "text", "met", "note", "position") VALUES ('01M065A8SA2KTD0M8ZKEQSK536', '01M0659D8ZXWYSFXE6M8ZM3CM2', 'Every `builds_on` edge a shipped skill instructs is either admitted by entry 6 or no longer instructed: spec → problem_brief, spec → product_brief, spec → discussion, and library document → audit are each covered by a test that writes the edge and reads the register''s verdict.', 1, '`tests/dependency-endpoints.test.js`, first test: every pair a shipped skill instructs is written through `create_dependency` and then read back through register entry 6 — spec→spec, spec→problem_brief, spec→product_brief, spec→discussion and library→audit for `builds_on`, adr→adr for `constrains` and for `supersedes`. Each row in the table names the skill and step that writes it. Driven by mutation: restoring the old hardcoded rule fails that test with "''builds_on'' does not admit spec → problem_brief".', 1);
INSERT INTO "quick_criterion" ("id", "quick_id", "text", "met", "note", "position") VALUES ('01M065AATMZWEFMSK5BV0RCJD2', '01M0659D8ZXWYSFXE6M8ZM3CM2', 'A pair the rule does not admit is still reported, named by edge id and by both end kinds — so the fix is a widened rule rather than a deleted check.', 1, 'Two tests, because the rule is now enforced in two places: an epic→spec `builds_on` is refused at the write with both the pair and the admitted set in the message and no row left in the table, and an edge written past the tool is reported by entry 6 with its id and both end kinds. The control deletes `builds_on`''s endpoint rows and shows the same call accepted, so the refusal is the data rather than the code.', 2);
INSERT INTO "quick_criterion" ("id", "quick_id", "text", "met", "note", "position") VALUES ('01M065ABV4S5M19640QS41P1A4', '01M0659D8ZXWYSFXE6M8ZM3CM2', 'The register''s prose at `dpm/src/integrity/register.js:24` says what entry 6 now admits and why, rather than describing the spec→spec-only rule it replaced.', 1, '`src/integrity/register.js:24` now says the entry reads `dependency_kind_endpoint` and declares nothing itself, why a kind with no rows is unconstrained rather than admitting nothing, that a story-ended edge is passed over, and that `create_dependency` enforces the same rule from the same source. The paragraph it replaced described the spec→spec rule and its deferral.', 3);
INSERT INTO "quick_criterion" ("id", "quick_id", "text", "met", "note", "position") VALUES ('01M0Z04X2Y7M1144ZQKTDGNB2H', '01M0Z04X2W3E7M5T9W6VJRR6KB', '`cpm/shared/skill-conventions.md` carries a top-level `## Disposition` section naming Fixed, Left alone, Unverified and Needs you in that order.', 1, '`## Disposition` sits between `## Conversational Output` and `## Written Deliverable Length`. The suite reads the four labels out of the section’s own bullets and compares the sequence, with a non-empty control so a changed bullet format cannot pass as an empty match.', 1);
INSERT INTO "quick_criterion" ("id", "quick_id", "text", "met", "note", "position") VALUES ('01M0Z04X308V5Z3F00SB8HRE0C', '01M0Z04X2W3E7M5T9W6VJRR6KB', '`CORE_SECTIONS` in `cpm/hooks/lib/conventions-core.sh` is unchanged, and the hook’s extract names Disposition in its index line without emitting the section’s body.', 1, 'Running the hook against the real shared file emits "Disposition" in the index line and not the body; a control assertion proves the extract emits a core section’s body, so the absence is meaningful. A fourth assertion checks no `### Disposition` exists, since a nested one would be emitted in full by a hook whose CORE_SECTIONS never names it.', 2);
INSERT INTO "quick_criterion" ("id", "quick_id", "text", "met", "note", "position") VALUES ('01M0Z04X32VCAZKR0YK20YDDWE', '01M0Z04X2W3E7M5T9W6VJRR6KB', 'Each of `do`, `quick`, `review`, `audit`, `inspect`, `pivot`, `archive` and `clean` instructs its closing report to use the convention, naming that skill’s own items rather than restating the four definitions.', 1, 'All eight reference it by name and each maps its own artefacts. A negative control confirms `brief` does not, and a further assertion confirms no skill reproduces the four definitions in place of naming its own items.', 3);
INSERT INTO "quick_criterion" ("id", "quick_id", "text", "met", "note", "position") VALUES ('01M0Z04X34H45JPG5YWJQW43G3', '01M0Z04X2W3E7M5T9W6VJRR6KB', 'The section states the four rules that give it teeth: the label follows the reader’s obligation rather than the run’s action; a disposition with no items renders no heading at all; an item fitting none of the four is not reported; and Unverified means the check was structurally impossible here, so a failure about how the run went is Needs you.', 1, 'All four are present and each is asserted by its own literal. Two skills needed the rules reconciled rather than repeated: `do`’s retro outcome and criterion-amendments block must speak when empty, and `audit`’s required section 6 is a rule about the file rather than the report.', 4);
INSERT INTO "quick_criterion" ("id", "quick_id", "text", "met", "note", "position") VALUES ('01M0Z04X35HVYVZVBH5PQACDBT', '01M0Z04X2W3E7M5T9W6VJRR6KB', '`cpm/hooks/tests/test-disposition-convention.sh` asserts criteria 1 to 3 with a negative control proving the assertions discriminate, and `bash cpm/hooks/tests/run-all-tests.sh` stays green.', 0, 'Half met, and recorded as not met rather than rounded up. The new suite passes 23 of 23. `run-all-tests.sh` is not green: `test-environmental-integration.sh` fails five assertions because `fixtures/coverage-baseline-46.tsv` was captured when CPM’s 46 specs lived in `docs/specifications/`, and the corpus has since moved to `docs/cpm/specifications/` while DPM publishes two of its own there — 48 on disk against a baseline of 46. That suite reads none of the ten files this change touches. Accepted as pre-existing at the Step 4 gate.', 5);
INSERT INTO "quick_criterion" ("id", "quick_id", "text", "met", "note", "position") VALUES ('01M0Z05YYVN4B47BXBB5JXMPVY', '01M0Z05YYS3TW9P6GF4D5E29NT', 'A dump whose requirements carry completeness claims restores into a database that still carries them.', 1, 'Asserted over the mechanism rather than over the ordering: `decay.test.js` builds a claimed requirement with a bound coverage row, dumps, restores into a fresh database, and reads the claim back. Ordering is how it is fixed today; surviving the restore is what has to stay true however it is fixed tomorrow.', 1);
INSERT INTO "quick_criterion" ("id", "quick_id", "text", "met", "note", "position") VALUES ('01M0Z05YYXJSC8HZ3M4ZGCCJDX', '01M0Z05YYS3TW9P6GF4D5E29NT', 'The dump emits the triggers that maintain a derived index before the rows, and every other trigger after them.', 1, '`dumpSchema` returns two halves and `dump` composes PREAMBLE, schema, rows, deferred. The split is `maintainsVirtualTable`, which asks what the trigger writes to rather than what it is called — a naming-convention test would defer a future index trigger and restore into an empty index, which is the false pass the existing exclusion logic already warns about.', 2);
INSERT INTO "quick_criterion" ("id", "quick_id", "text", "met", "note", "position") VALUES ('01M0Z05YYZ8HXB7PDJRWJ2ARMQ', '01M0Z05YYS3TW9P6GF4D5E29NT', 'The regression fails without the fix.', 1, 'Verified by reverting the composition in `dump/index.js` to the old order and re-running: 13 pass, 1 fail, and the failing one is the new test.', 3);
INSERT INTO "quick_criterion" ("id", "quick_id", "text", "met", "note", "position") VALUES ('01M0Z05YZ0Y8NGXYMSK759V6Z3', '01M0Z05YYS3TW9P6GF4D5E29NT', '`node --test` stays green across the whole DPM suite.', 1, '819 tests, 819 passing. 818 before the new test, and none of them had caught the defect — the round-trip guard in `rebuild` was the only thing that did.', 4);
INSERT INTO "quick_criterion" ("id", "quick_id", "text", "met", "note", "position") VALUES ('01M0Z05YZ25EJ04AK4ZNM71JXN', '01M0Z05YYS3TW9P6GF4D5E29NT', 'This project’s committed dump and database carry the 40 claims, in the new ordering, with the guard clean.', 1, 'The committed dump was in the old ordering, so restoring it would still have decayed the claims. Repaired by restoring it, re-asserting each claim through `claimComplete` with the recorded timestamp, and refusing unless every one of the 40 hashes reproduced from the bound set — all 40 did, so the values were recovered rather than invented. The re-emitted dump is byte-identical in size to the committed one and has a zero-line difference when sorted: a pure reordering. `dpm-guard.js` reports 21 projected files and the dump matching the database.', 5);
INSERT INTO "quick_criterion" ("id", "quick_id", "text", "met", "note", "position") VALUES ('01M0Z0GPCEH7N7VX3KPKXW7CTR', '01M0Z0GPCB1JYVZRWWRC88Z880', 'A rebuild whose dump does not survive its own restore leaves the database as it found it.', 1, 'The round-trip check moved inside the staging block, before `renameSync`. A refusal now discards the staging file and returns without the target having been touched.', 1);
INSERT INTO "quick_criterion" ("id", "quick_id", "text", "met", "note", "position") VALUES ('01M0Z0GPCG9Z499Z4QVK3KX6MM', '01M0Z0GPCB1JYVZRWWRC88Z880', 'The refusal still says what it refused, in the words both callers print.', 1, 'The catch re-throws a `RebuildError` unwrapped and frames only errors arriving from elsewhere. Without that, a round-trip refusal raised inside the try would be reworded as "the dump did not restore into…", which is a sentence about a restore that in fact succeeded. `merge.test.js`’s verbatim-message assertion still passes.', 2);
INSERT INTO "quick_criterion" ("id", "quick_id", "text", "met", "note", "position") VALUES ('01M0Z0GPCH4X3MAY8SA0MD9TTW', '01M0Z0GPCB1JYVZRWWRC88Z880', 'The assertion that claimed this property can now see it fail.', 1, 'It could not before: the fixture built the refused dump by editing the same dump the database was restored from, so it compared `[already-here]` against `[already-here]` and passed either way. The refused dump now describes a different database, with a control asserting the two differ. Verified by restoring the old ordering and re-running: the test fails.', 3);
INSERT INTO "quick_criterion" ("id", "quick_id", "text", "met", "note", "position") VALUES ('01M0Z0GPCKA3QYY438AXAEBX9R', '01M0Z0GPCB1JYVZRWWRC88Z880', '`node --test` stays green across the whole DPM suite.', 1, '819 tests, 819 passing.', 4);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M050SJFST75N3GFZ64WNPTND', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'FR1', 'functional', 'must', NULL, NULL, 'The server reports when a newer version of the plugin is installed alongside the version it is running from.', 0, '2026-08-16T00:00:00Z', '7454a44e4cf40e7772d9305bae30cf75da18e6c76ed8473cad438ba227b50ae4');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M050SM0JB72VCAW0BVRQCXG6', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'FR2', 'functional', 'must', NULL, NULL, 'The database records the version of the plugin that last wrote to it. The record is made by a server that writes, and never by one that only observes — a read-only launch leaves it as it found it.', 3, '2026-08-16T00:00:00Z', '077d414560b00537f48c593d00caa06139b751548280cb3454f34475b99077e2');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M050SSS6FCCYF8A9QZWQZ7DY', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'FR1a', 'functional', 'must', NULL, '01M050SJFST75N3GFZ64WNPTND', 'The neighbour check is evaluated at the moment it is reported, never cached from server start. The observed failure arrived twenty hours into a running session, when a check evaluated at start had already found nothing and been right to.', 1, '2026-08-16T00:00:00Z', '71204268ee98a567f4f02359408d1234a5d6957c45ef3a3044f427799f303808');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M050SWEGP80AYH58ZK0P47FG', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'FR1b', 'functional', 'must', NULL, '01M050SJFST75N3GFZ64WNPTND', 'The neighbour check completes without error when the plugin root is not a version directory, reporting could-not-check rather than failing and rather than claiming no skew. A plugin loaded from a working tree is the ordinary case for anyone developing dpm, and it produces the same "found nothing" as a genuinely current install — only one of which is honestly a no-skew answer.', 2, '2026-08-16T00:00:00Z', 'b0527c39097a0b52737fcb8d3e8e9570ae0361011b952e52cdff535674435cf2');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M050SYMMPF5JV138K22HFYK4', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'FR2a', 'functional', 'must', NULL, '01M050SM0JB72VCAW0BVRQCXG6', 'The recorded version is written only when the writing server''s version is greater than the version already recorded, so an unchanged project produces an unchanged dump.', 4, '2026-08-16T00:00:00Z', '1edf1fc253c075b49ceca7a5b41a05ce0518e29d8aa018970ad6b17d86f33cf3');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M050T08GZRV3X57AD61PWZ0N', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'FR3', 'functional', 'must', NULL, NULL, 'The server reports when the plugin version recorded in the database is newer than its own.', 5, '2026-08-16T00:00:00Z', 'ae8d7bd24ee745dfade5b05ac5ca5a5f95f0808c414f9ed3e5200f39cf427c2f');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M050T1XRVWJYY3T5XXJNXTPB', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'FR4', 'functional', 'must', NULL, NULL, 'A reported skew names the version running, the newer version found, and what to do about it, and the sentence saying so is composed in one place rather than assembled separately by each caller. Naming the remedy is the existing convention: the dump-staleness message names publish, which is both true and the fix. One composer is what keeps the tool response and the stderr line from drifting into two accounts of the same skew.', 6, '2026-08-16T00:00:00Z', '58452d1befc5412fe53799c1487c53cace8382f95820905c5f6654df7dde601b');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M050T4QAWVSBRF17V42XSGVA', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'FR5', 'functional', 'must', NULL, NULL, 'The report distinguishes checked-and-found-no-skew from could-not-check. A check that silently did not run is the defect `checkIntegrity` already guards against by counting what it checked rather than reporting only what failed.', 7, '2026-08-16T00:00:00Z', '67974f9084860a6a78bdb5cb8f62f3e3ec965e5435282aeb5cc889306dc9cf87');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M050T70SV8AT324K0BEZ2NY2', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'FR6', 'functional', 'must', NULL, NULL, 'A skew known at database open is written to stderr, in the manner of the existing ahead-message. In practice this carries the database-stamp skew; the neighbour skew is usually absent at open and arrives later.', 8, '2026-08-16T00:00:00Z', '0903de06ca58860775fda7079dcbc20bbefc7f4573e4538d11cbe674345b4024');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M050T8WP5MTS43W8JCHRM0HM', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'FR7', 'functional', 'should', NULL, NULL, 'A server launched read-only reports both skews. It never reaches `start()`, so as things stand it would learn of neither — and a board observing many projects is the surface where an unnoticed stale server misreports the most of them.', 9, '2026-08-16T00:00:00Z', 'ab6dcdac0107e783690b8211d494ef1c7fd97fef97f75be80a33c6ca7b236686');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M050TB4BT5FV666XQ878A5A0', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'FR8', 'functional', 'could', 'deferred', NULL, 'The neighbour check also consults the installation registry, catching a skew after the older sibling directories have been swept.', 10, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M050TDKCNVM023XFMKM2YT85', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'FR9', 'functional', 'wont', 'out_of_scope', NULL, 'Refusing or degrading tool calls on a backward skew. The forward case earns a read-only tool set because an older server can damage a newer database; the backward case cannot, and a server that refused to serve because a newer plugin exists would cost more than the under-seeding it was protecting against.', 11, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M050THQ89YAFXGN0CEHW85QJ', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'FR10', 'functional', 'wont', 'out_of_scope', NULL, 'Loading seed data or code from a newer sibling version directory in order to self-repair. It is the fix that suggests itself once the neighbour is visible, and it runs a newer release''s data through an older release''s guards and schema — the precise combination `migrate()` refuses in the forward direction. Recorded so the reasoning outlives the impulse.', 12, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M050TKQCY5G6Q54HYH2SFQJA', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'FR11', 'functional', 'wont', 'out_of_scope', NULL, 'Restarting or reloading the server into the newer version. Which version directory a server runs from is chosen by the MCP client at launch, and a process that re-executed itself elsewhere would be overriding that choice from inside.', 13, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M051AB08BP2SRQPB92XZE056', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'NFR1', 'non_functional', 'must', NULL, NULL, 'The neighbour check costs one bounded directory read per report — no recursion, no process spawn, no network call. It runs on every report rather than once per session, so its cost is paid repeatedly and has to stay negligible.', 14, '2026-08-16T00:00:00Z', 'ecb1a15783fd7c2a592ffc25b04154167ea5659163964d7955bc018ca912cab1');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M051AD1B1DTGSST2N23P7VY1', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'NFR2', 'non_functional', 'must', NULL, NULL, 'A skew check that cannot complete degrades to could-not-check. It never fails the tool call and never stops the server. Paired with FR5: FR5 gives the report a way to say it, this gives the failure somewhere to go.', 15, '2026-08-16T00:00:00Z', '6feb6468c85bb5dac61a1d56cd61601b70c730a25a5d9f6a042caaaa7d7ed058');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M051AFK6WGGR51HRDBJZ3BBP', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'NFR3', 'non_functional', 'must', NULL, NULL, 'A session that neither upgrades the plugin nor changes planning data leaves the committed dump byte-identical. A stamp written on every start would diverge the dump every session, the pre-commit guard would fire on commits that changed nothing, and a guard that fires on nothing stops being read — which costs more than this feature is worth.', 16, '2026-08-16T00:00:00Z', 'c53d48858beaeba64bb6d9356352b2d9c8aa0d76172c250d9624ca7dea845313');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M051AH8HRSBNM3HQ4EDKZEQH', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'NFR4', 'non_functional', 'must', NULL, NULL, 'The neighbour check reads only. It creates no file and no directory, and writes nothing anywhere — including under a read-only launch, whose whole guarantee is inertness.', 17, '2026-08-16T00:00:00Z', '816caa8265a44583ff089e4d3f7d419acacfd6959be703f6e7d44e62181c6181');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M051AM2H7N225EFYN5FJ12K3', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'NFR5', 'non_functional', 'must', NULL, NULL, 'The coupling to the host''s plugin cache layout is recorded in the project''s maintenance record, and named from no skill file. The layout is the host''s to change and not ours to rely on quietly; a pointer from a skill would be a line every invocation pays for.', 18, '2026-08-16T00:00:00Z', '591fd00c58102918ab32ffc622c0d0b419d0a3bbd464421545a634d37f7c092d');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M051FXVRATSJ9792ABHWG7ZH', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'ENV1', 'environmental_requirement', 'must', NULL, NULL, 'Development: Node 22.5.0 or later, matching `engines.node`. Checkable by comparing the running `process.version` against the floor the server already states as `REQUIRED_NODE`.', 19, '2026-08-16T00:00:00Z', '6abf34a12b8f1af45a1118c46e17f69549853a56142509db57e89bcf6effad85');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M051FZZSFG41WN4XKAXYESRJ', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'ENV2', 'environmental_requirement', 'must', NULL, NULL, 'Development: the suite runs via the built-in `node --test` runner with no install step. Checkable by running the test script on a clean checkout. This project has no CI, so the suite is run by whoever is at the keyboard — a runner needing setup is a runner that stops being run.', 20, '2026-08-16T00:00:00Z', 'cd64a44b23002e1b14c9d8930fb21867616e91663c5d1bad1dcdc2693db580c1');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M051G26K8RP8E6QZDKGAX8RB', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'ENV3', 'environmental_requirement', 'must', NULL, NULL, 'Development: a fixture standing in for a plugin cache layout — a directory holding sibling version directories — that the neighbour check can be pointed at. Checkable by a test that constructs one and asserts the check''s verdict against it.', 21, '2026-08-16T00:00:00Z', '04bbd13e1c7ae3e9a4962a99879d8780ea26d6d0b297d70b52bb9d3f763e05ef');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M051G46647GRRP5FMHZYGMX7', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'ENV4', 'environmental_requirement', 'must', NULL, NULL, 'Production: Node 22.5.0 or later on the machine running the MCP client. Checkable by the floor check the entry point already performs before anything reaches `node:sqlite`.', 22, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M051G66CR82G4ZNEQYCM5V83', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'ENV5', 'environmental_requirement', 'must', NULL, NULL, 'Production: the running plugin''s own directory is derivable from the module''s URL at runtime. Checkable by resolving it and asserting it names the directory the module was loaded from. This is what makes the neighbour check possible without the host handing us anything.', 23, '2026-08-16T00:00:00Z', '2fbc742b105a265b3e615bdc99fcb3743c40c8c914b9e014ce8c288ac50deddf');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M051G8YMR8QX20G7SWFWNC4B', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'ENVX1', 'environmental_restriction', 'must', NULL, NULL, 'Development: no runtime or development dependency may be required. Checkable by asserting `dependencies` and `devDependencies` are both empty in `package.json`. A semver comparison is the obvious place a package would creep in, and the parser this needs already exists in `node-floor.js`.', 24, '2026-08-16T00:00:00Z', '41ad8afa3ce451d4d3c5fd67ee1cc259d730dbdcb7a6d9812fb5075a04375f2e');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M051GBWM7XJNH6W0HTCEN3M0', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'ENVX2', 'environmental_restriction', 'must', NULL, NULL, 'Development: the suite must not require the real plugin cache or the user''s home directory. Checkable by the neighbour check taking its root as an argument, and by a test asserting it reads only the path it was given. Without this the obvious implementation passes on the author''s machine for reasons unrelated to the code being correct.', 25, '2026-08-16T00:00:00Z', '0e6c2c751ba18656f258bf4e5d17223c45e28a037141dca72c02317f68e41bf4');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M051GDWWCKCKECZJ1PQSW3TZ', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'ENVX3', 'environmental_restriction', 'must', NULL, NULL, 'Production: an environment variable naming the plugin root must not be required. Checkable by the resolver taking no value from `process.env`. The host expands its plugin-root placeholder into the launch arguments, and nothing guarantees it in the process environment.', 26, '2026-08-16T00:00:00Z', 'b20976f808b0b05743f14036eb6036f65739dfd4586624025a592deff947fda3');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M051GFMNV8HS8QM80BWP7S0T', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'ENVX4', 'environmental_restriction', 'must', NULL, NULL, 'Production: network access must not be required. Checkable by asserting no path this spec adds makes an outbound call. This forecloses the tempting implementation of FR8 — asking the marketplace what the current version is — which would make a local diagnostic depend on being online.', 27, '2026-08-16T00:00:00Z', '995f45471a94b5327cd96e6923f5a35103bfa3705b6b67a60f8fa54b4b26e76b');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05271SG9G0BYGH25VE7SAKB', '01M050N7S7YF827QD2CH0TVTFK', 'spec', 'ENV6', 'environmental_requirement', 'must', NULL, NULL, 'Development: a temporary filesystem location the suite can create, write to and remove. Checkable by a test that creates one, writes into it and asserts it is gone afterwards. Reached from Step 6d rather than elicited: several integration criteria write and compare real files — the two dump comparisons, the filesystem-unchanged assertion, and the construction of ENV3''s sibling directories — and nothing recorded said the suite could.', 28, '2026-08-16T00:00:00Z', '5905f48d9204770abc5de2e68c0d5619f9aa49642068eb6fe7747d185fe0c1d1');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05JW91578GQ942N25MEHN7Y', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'FR1', 'functional', 'must', NULL, NULL, 'Every key the CPM board binds carries the same meaning on the DPM board: `r` refreshes, `R` clears the cache, `a` registers a project, `x` unregisters the highlighted one, `z` shows or hides retired work, and the eight already shared — `q`, `l`, `o`, `t`, `c`, `space`, `←` and `→` — keep theirs. A capability the DPM board reaches only through the command palette today gains its CPM key.', 0, '2026-08-16T00:00:00Z', 'c95535c882648e457c2ea9a8df7074653d1eb71bc44732f6947ce951b277b384');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05JWBSBWAGG1996DS44GNY8', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'FR2', 'functional', 'must', NULL, NULL, 'Retired work is hidden when the board opens and `z` toggles it, where retired means `complete` together with the two states `status_model.RETIRED` already names — `superseded` and `withdrawn`. Each press says which way it went, as the CPM board''s does.', 1, '2026-08-16T00:00:00Z', 'b48f221d6a2f3f49c86b159834df4debbcfd63d5eceb058be571b62410291096');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05JWDT6D746WHHMYMX25W99', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'FR3', 'functional', 'must', NULL, NULL, 'Every capability the DPM board has and the CPM board lacks is bound to a key that collides with nothing in the CPM map. The forced re-read gives up `R` and takes `ctrl+r`; search and coverage gaps keep `ctrl+f` and `ctrl+g`.', 2, '2026-08-16T00:00:00Z', 'e3b852df33c54b43ef6327e661099657a1b91f20df0991e13f5be83761e23477');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05JWFWE9YFDG4F6TZYEW28Q', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'FR4', 'functional', 'must', NULL, NULL, 'The highlighted row renders as a muted bar in the row''s own colour, blended partway toward the background, as the CPM board''s `InverseOptionList` paints it — and Textual''s default highlight block does not show through it.', 3, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05JWHYN3X2KS6M596QVZCVW', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'FR5', 'functional', 'must', NULL, NULL, 'The live pill and the integrity badge sit against the right edge of the projects column whatever width that column has, rather than following the progress figure, and each keeps its own colour over the row''s status colour.', 4, '2026-08-16T19:22:00Z', '7dfcfc7036d9f5ba53b884ab660010e681e1c754d3d470c0551c8a022fa05dc8');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05JWM2TDZDXYM5YP2PBJFQF', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'FR6', 'functional', 'must', NULL, NULL, 'The epic and story preview panels render markdown rather than showing its source: headings, emphasis, lists and tables draw as the CPM board draws them, at the panel''s own width, re-rendered when the panel is resized, with the rendered text still selectable.', 5, '2026-08-16T20:55:00Z', '4374934e8528ada50f807d898adf56ec1e1a0aaaab77b2319f215b3a083c372d');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05JWRFR5P502VH5TYJC6RZQ', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'FR6a', 'functional', 'must', NULL, '01M05JWM2TDZDXYM5YP2PBJFQF', 'The preview builders emit markdown source rather than plain text, so that the structure they compose from rows — the document''s title, each section''s heading, a story''s criteria and tasks — renders as headings and lists rather than as prose that happens to begin with a dash.', 6, '2026-08-16T20:55:00Z', '0c9c824777a0ebc89502b1333e6485dba6bd8d90d90d35987a2dbe656ed48331');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05JWTJ2VA95F698PF5AJ2JH', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'FR7', 'functional', 'should', NULL, NULL, 'The footer labels and the command-palette entries describe the keys as they stand after FR1 and FR3, and use the CPM board''s wording wherever the action is the same one.', 7, '2026-08-16T00:00:00Z', '683dda777c566ba696aa5ec3c1adaa38c8530bdcce026f4db1c92155f1798afd');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05JWWMC9BJW4624YZVQTR9Q', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'FR8', 'functional', 'must', NULL, NULL, 'The two boards are compared surface by surface beyond the four differences already established, and every further difference found is either closed or recorded as deliberate. A difference nobody has looked at is neither.', 8, '2026-08-16T00:00:00Z', '4ed6f7c38475c0286e099af7e05e47959c33ac130cf2902d7b8dac3044d0f920');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05JWZH4VAJACEP33M4S1P1C', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'FR9', 'functional', 'must', NULL, NULL, 'A difference of the kind this spec closes fails something mechanically the next time one board moves and the other does not, rather than waiting to be noticed by a user moving between them. What that mechanism is, is decided in Section 4.', 9, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05JX24QESMJ6QPQHHK4RT9W', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'FR10', 'functional', 'wont', 'out_of_scope', NULL, 'The two boards'' state-colour palettes are not reconciled. They are keyed on different state vocabularies rather than being two colour schemes over one, and the colours already agree for the states both models have.', 10, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05JX3QG6PBR91N46ECWP4NG', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'FR11', 'functional', 'wont', 'deferred', NULL, 'The two boards are not merged into one codebase and share no installable package. Each stays a self-provisioning single-file script, and FR9''s mechanism has to work within that.', 11, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05K8WX9AVDRMSE0HGKNB8CZ', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'NFR1', 'non_functional', 'must', NULL, NULL, 'Moving the cursor through a list stays responsive. Rendering the highlighted row''s preview does not block key handling, and a held arrow key does not queue one render per row passed over. The markdown raster is new CPU work on a path that already runs per highlighted row, and it is width-specific, so it runs again on every resize.', 12, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05K8Z0AFQMYF2JCBWNCF1Y7', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'NFR2', 'non_functional', 'must', NULL, NULL, 'A preview the renderer cannot make sense of — malformed markdown, a pathological table, a body that is one very long line — renders as something and does not take the board down. The board is a viewer over projects it did not write, and one bad row in one project must not close it for the others.', 13, '2026-08-16T20:55:00Z', 'e1cf4342b68c0bcfdf6158c3ef1a9edcf9440becf5ab92e946341a12b98ce979');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05K90WP11SZWPNQZYH6W26C', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'NFR3', 'non_functional', 'must', NULL, NULL, 'The highlighted row and the pill stay legible on a terminal that does not report truecolor. The cursor blends two colours and the raster asks for a colour system by name, so both are assumptions about the terminal rather than about the code.', 14, '2026-08-16T20:55:00Z', '1f4398c4f75ae236cad179e2a8eb9918e905c2785ab61a89a540170b2240bf2c');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05KAB1GYPQKYV0AT1ZFCB5P', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'ENV1', 'environmental_requirement', 'must', NULL, NULL, 'Development: `uv run pytest` from `dpm/tools/board` runs the suite, with pytest 8 or later, pytest-asyncio 0.24 or later, and `asyncio_mode = "auto"`.', 15, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05KADV6YVN6NAZHT48PRCQH', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'ENV2', 'environmental_requirement', 'must', NULL, NULL, 'Development: Textual 0.80 or later, with the dependency list in `pyproject.toml` and the PEP 723 inline block at the top of `board.py` naming the same packages. A package in one and not the other is one the suite has and the board does not.', 16, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05KAF6BY0J9X2GN020JK71N', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'ENV3', 'environmental_requirement', 'must', NULL, NULL, 'Development: a markdown renderer importable from a package the board already declares. Rich arrives with Textual, so FR6 adds nothing to either dependency list.', 17, '2026-08-16T17:41:06Z', 'c2af969b25c6705bd150f1264f3d9280911b2251f5463a9999ba445a336348e6');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05KAH8JWD17744XDY3S9PTN', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'ENV4', 'environmental_requirement', 'must', NULL, NULL, 'Development: the CPM board''s source is readable at `cpm/tools/board/` relative to the marketplace checkout root, which is what FR8''s comparison and FR9''s mechanism read.', 18, '2026-08-16T00:00:00Z', 'c07694d692ecece5f158ee3ff44c5dc07e87902d40e0d30b5bd478cd532c080f');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05KAKAN0ECNYACZGVVBX2QM', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'ENVX1', 'environmental_restriction', 'must', NULL, NULL, 'Development: the suite must not require network access. The guard that enforces it is autouse, so this is a property of every test rather than of the one that remembered to ask for it.', 19, '2026-08-16T17:41:06Z', '2a6cf6793ee8a742778660a557a8db0e09e8977d8b7ddeed96bec72c5950c119');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05KAND02WHYZQQRD2C2SFX2', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'ENVX2', 'environmental_restriction', 'must', NULL, NULL, 'Development: this work must not require a package outside `board.py`''s inline block, and dpm itself must gain no dependency from it.', 20, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05KAPS3B31FHN8BYMR70S20', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'ENV5', 'environmental_requirement', 'must', NULL, NULL, 'Production: Python 3.11 or later on the machine the board runs on, provisioned by `uv run` from the inline block.', 21, NULL, NULL);
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05KARYFQ5C7K2APQ4MPKY35', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'ENVX3', 'environmental_restriction', 'must', NULL, NULL, 'Production: the board must not require the CPM plugin to be installed or readable. It runs from the plugin cache, where only its own tree exists, so FR9''s mechanism cannot be something the board reaches for at runtime.', 22, '2026-08-16T00:00:00Z', '79b1152d009dd4e7b031f96a342ceeaba2ae05f96eaa5d9535e8d9e67e2f4b3c');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05KATM4Y8TK1NS72EJVGFV9', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'ENVX4', 'environmental_restriction', 'must', NULL, NULL, 'Production: the board must not require a truecolor terminal. The cursor blends two colours and the raster names a colour system, and neither may be the thing that decides whether the board is legible.', 23, '2026-08-16T20:55:00Z', '1404baeec264a5c80a1f0c4de817b605ee98438fa6a0e7a332657f77708f41e6');
INSERT INTO "requirement" ("id", "spec_id", "spec_kind", "label", "class", "moscow", "exclusion", "parent_id", "text", "position", "coverage_claimed_at", "coverage_claim_hash") VALUES ('01M05MJ4RHTDW90814W6QTH1A3', '01M05J7VD7PWH32KWMND9MGHMN', 'spec', 'ENV6', 'environmental_requirement', 'must', NULL, NULL, 'Development: a fixture project whose database holds epics and stories in every state the model defines, retired ones included, and at least one document long enough to time a render against. FR2''s hide-retired criteria and NFR1''s timing criterion both assume it, and neither can be checked without it.', 24, '2026-08-16T17:41:06Z', '82175d4e1f7ed029836d9ed642e47cc669b88aba3f575ed680fe56cb2fd14c1e');
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051TBFX7E95TB876RV668HE', '01M050SJFST75N3GFZ64WNPTND', 'Given a root holding the running version and a higher-numbered sibling, the check reports a skew naming the higher version.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051TCZYEB1N87469MA9K0TE', '01M050SJFST75N3GFZ64WNPTND', 'Given a root whose siblings are all lower than or equal to the running version, the check reports no skew.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051TEJSB2XEGC0VBWR5V707', '01M050SJFST75N3GFZ64WNPTND', 'The check reports a skew for a sibling lower than the running version. A reversed comparison satisfies the first criterion on any machine with more than one version installed, so the first criterion alone does not pin the direction.', 'must_not', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051THCGRV518WES6VFC0QPB', '01M050SSS6FCCYF8A9QZWQZ7DY', 'Two consecutive reports against a root that gained a higher sibling between them return different verdicts.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051TKHZA6VAENCTS8SPWJTS', '01M050SSS6FCCYF8A9QZWQZ7DY', 'With the check deliberately memoised, the two-consecutive-reports criterion fails, and the failure has been observed and read rather than assumed. This requirement exists because a start-time check would have been silently wrong for twenty hours; a test unable to distinguish a cached verdict from a fresh one reproduces the defect it was written to catch.', 'control', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051TN2ATPKBMTAR0JJG73WM', '01M050SWEGP80AYH58ZK0P47FG', 'Given a root whose name does not parse as a version, the check reports could-not-check.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051TQPRFBD4RDE03W6HDSGA', '01M050SWEGP80AYH58ZK0P47FG', 'Given a root with no sibling directories at all, the check reports could-not-check rather than no skew.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051TTAKHBRAHVKC5R8CSZ8D', '01M050SWEGP80AYH58ZK0P47FG', 'The check throws for an unreadable or unparseable root.', 'must_not', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051WPWSFWJ6JKHX42F2WTRY', '01M050SM0JB72VCAW0BVRQCXG6', 'A database started by a server at version X carries X as its recorded plugin version.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051WRPMNHYZ5C6C372ABPKV', '01M050SM0JB72VCAW0BVRQCXG6', 'A database migrated from before the stamp existed acquires the running version on the next start.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051WTC2610QCJ66WZ4Z1FQ5', '01M050SM0JB72VCAW0BVRQCXG6', 'A read-only launch writes the stamp. The read-only path exists so a board can observe every registered project without touching any of them; a stamp written on observation would diverge every one of those projects from its committed dump, and the owner would find the guard refusing a commit in a repository they had not opened.', 'must_not', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051WVXVPHHPN2H39DD9Y4DR', '01M050SYMMPF5JV138K22HFYK4', 'A server at the recorded version leaves the row untouched.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051WXGY1NBENQV371WWJQFK', '01M050SYMMPF5JV138K22HFYK4', 'A server below the recorded version leaves the row untouched — the stamp never moves backwards.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051WZ06D57PMQ676MFKJCE2', '01M050SYMMPF5JV138K22HFYK4', 'A server above the recorded version replaces it.', 'must', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051X0FKZ98Z9V5989SF2V2Y', '01M050SYMMPF5JV138K22HFYK4', 'The row carries a value that differs between two runs of the same version. This is NFR3 stated where it can be checked: a timestamp column would satisfy every other criterion here and still diverge the dump on every start, which is the exact failure the requirement exists to prevent — while looking like good practice.', 'must_not', 3);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051X1YG1EMZ0QVMBZNGV51H', '01M050SYMMPF5JV138K22HFYK4', 'With the write made unconditional, the criterion that a server at the recorded version leaves the row untouched fails, and that failure has been observed and read rather than assumed.', 'control', 4);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051X3MJGQ517REPGWQJVHT0', '01M050T08GZRV3X57AD61PWZ0N', 'A database stamped above the running version produces a skew naming both versions.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051X5PXSZW7XZECRN3G0QZN', '01M050T08GZRV3X57AD61PWZ0N', 'A database stamped at or below the running version produces no skew.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051X7BW2SS23NPB29ZHFKZ0', '01M050T08GZRV3X57AD61PWZ0N', 'A database whose stamp table is absent produces could-not-check rather than no skew. This is the read-only launch against a project the release has never opened: the table will not be there, and no-skew would be a lie told confidently.', 'must', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051Z4AKAQ4JTHJ4HFEV1DPS', '01M050T1XRVWJYY3T5XXJNXTPB', 'A reported skew contains the running version, the newer version found, and a remedy naming a session restart.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051Z6PN842RF5DXJMPZF2WN', '01M050T1XRVWJYY3T5XXJNXTPB', 'The skew sentence is composed in more than one place. This extends the rule the ahead-message already holds — one sentence serving both bring-ups, so a reader parsing the line matches one wording rather than two that are one edit from disagreeing. Two detectors reporting through two channels is four opportunities to write that sentence four times.', 'must_not', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051Z88XTCF9TD9KYBDFMZAX', '01M050T4QAWVSBRF17V42XSGVA', 'The skew field is present in the response when no skew was found.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051ZAE9DGY9WJ6FQ8MGX661', '01M050T4QAWVSBRF17V42XSGVA', 'The three states — skew found, no skew, could not check — are distinguishable without parsing message text.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051ZBZR5PA0GE6NG2K27T8W', '01M050T4QAWVSBRF17V42XSGVA', 'A check that could not run renders as no skew.', 'must_not', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051ZDJ4V1CHVZ3DXJ0YVRT1', '01M050T4QAWVSBRF17V42XSGVA', 'With could-not-check collapsed into no-skew, FR1b''s criteria fail, and that failure has been observed and read rather than assumed.', 'control', 3);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051ZFZ032E4Y7C71NS00Z60', '01M050T70SV8AT324K0BEZ2NY2', 'A database stamped above the running version writes a line to stderr when opened.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051ZHP7FFBBTNJZJFCGC3JC', '01M050T70SV8AT324K0BEZ2NY2', 'A clean open writes anything to stderr. This continues the rule the project already holds — a clean session is silent there — which is what makes any line that does appear worth reading.', 'must_not', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M051ZKFEXZFV2W0257B57DPX', '01M050T8WP5MTS43W8JCHRM0HM', 'A read-only launch''s integrity response carries the same skew field, in the same three states, as an ordinary one.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M0521HBXYWCMC53PZBYR7VR9', '01M051AB08BP2SRQPB92XZE056', 'The check performs exactly one directory read per invocation. Counting reads means the reader is injectable — a seam falling out of the criterion rather than a preference, and the same seam ENVX2 needs.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M0521JYZ5YBG2BQHG4WQB5DB', '01M051AB08BP2SRQPB92XZE056', 'The check recurses into subdirectories.', 'must_not', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M0521NPJTBGKBW3F9JZ6AJN8', '01M051AB08BP2SRQPB92XZE056', 'The check spawns a process or opens a socket.', 'must_not', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M0521QD2BDHC8HGFVHEDZ5ES', '01M051AD1B1DTGSST2N23P7VY1', 'A directory read that throws produces could-not-check and a successful tool response.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M0521S0F3NDQJGMG0VKX8XDR', '01M051AD1B1DTGSST2N23P7VY1', 'An error from the check propagates out of the tool handler.', 'must_not', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M0521V0D5326TK967Y2MG48A', '01M051AD1B1DTGSST2N23P7VY1', 'With the error handling removed, the criterion that a throwing read produces could-not-check fails, and that failure has been observed and read rather than assumed.', 'control', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M0521WNR1F2KCHXEJRQVK3MA', '01M051AFK6WGGR51HRDBJZ3BBP', 'Two consecutive starts at the same version, with no planning data changed, produce byte-identical dumps.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M0521YA35YV05139S92NQJN0', '01M051AFK6WGGR51HRDBJZ3BBP', 'A start that raises the recorded version does change the dump. Without this positive half, a comparison that is broken — reading the wrong file, comparing nothing to nothing — passes the first criterion perfectly.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M0521ZWYKTSPN8FX984QRDG2', '01M051AH8HRSBNM3HQ4EDKZEQH', 'After a report, the filesystem beneath and beside the plugin root is unchanged.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05221FRMDZ1T6GNBPQRBXWS', '01M051AH8HRSBNM3HQ4EDKZEQH', 'The check creates a file or directory anywhere.', 'must_not', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M052230NFE5D4YN76Y8XCH5E', '01M051AM2H7N225EFYN5FJ12K3', 'The maintenance record documents the assumed plugin cache layout and what breaks if the host changes it. Manual because whether a written record actually explains the coupling is a judgement about prose; the automatable version — asserting the file contains certain words — would pass on a heading with nothing under it, which measures the wrong thing.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05225Q4DMXXEZFYKHHP29XD', '01M051AM2H7N225EFYN5FJ12K3', 'Any file under the skills directory names the maintenance record''s path.', 'must_not', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M0524E0N4ND8DKZ5N0BGJFFS', '01M051FXVRATSJ9792ABHWG7ZH', 'The running Node satisfies `REQUIRED_NODE`, and `engines.node` equals it.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M0524FM7138ATHKDMN38HGGG', '01M051FZZSFG41WN4XKAXYESRJ', 'The test script invokes only the built-in runner, with no binary resolved from `node_modules`.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M0524HBPKPGKKYX42KKPJ39Y', '01M051G26K8RP8E6QZDKGAX8RB', 'A constructed directory of sibling version directories exists in the suite, and the check reports a verdict against it.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M0524K76BDESFGQ3H8KSA1PE', '01M051G46647GRRP5FMHZYGMX7', 'On the host, launching below the floor produces the floor message rather than the raw unknown-builtin-module error.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M0524N9RHH8DJ2G1T4YSQMVK', '01M051G66CR82G4ZNEQYCM5V83', 'Resolving from the module''s own URL names the directory the module was loaded from.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M0524QQ515E0J1KW7J078G3M', '01M051G8YMR8QX20G7SWFWNC4B', '`dependencies` and `devDependencies` are both empty.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M0524SHWXQHBN7QS7QATKDKA', '01M051GBWM7XJNH6W0HTCEN3M0', 'The check reads only the path it was given.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M0524VCM0R7758DB5VVD8CAA', '01M051GBWM7XJNH6W0HTCEN3M0', 'Any path a test resolves runs through the user''s home directory.', 'must_not', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M0524X0GJ00QMKYP5P1ZMQ0D', '01M051GDWWCKCKECZJ1PQSW3TZ', 'The resolver reads no value from `process.env`.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M0524YSBF3VN42ZN5GJPSZ52', '01M051GFMNV8HS8QM80BWP7S0T', 'No path this spec adds makes an outbound call.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M0527DQBQZNY61FXTFF9YT2A', '01M05271SG9G0BYGH25VE7SAKB', 'A test creates a temporary location, writes into it, and asserts it is gone afterwards.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05KY55AN0D0FF59GR876VP9', '01M05JW91578GQ942N25MEHN7Y', 'Driving a running board: `r` re-reads every registered project, `R` empties the cache, `a` opens the register picker, `x` unregisters the highlighted project, and `z` toggles retired work.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05KY772CX2185D8PGM9P9NV', '01M05JW91578GQ942N25MEHN7Y', 'For every action the CPM board binds, read from that board''s own source, the DPM board binds the same action to the same key. The claim is stated over CPM''s map as the source rather than as an equality between the two maps, so a key either board legitimately gains does not fail it.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05KY8KEP08A7MNZ1XSJXK0A', '01M05JW91578GQ942N25MEHN7Y', 'No key the CPM board binds does something different on the DPM board.', 'must_not', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05KY9ZHRNB9Z2RYMJR462BZ', '01M05JWBSBWAGG1996DS44GNY8', 'A board opened over a project holding complete, superseded, withdrawn and live rows shows only the live ones; `z` reveals all four groups; `z` again returns to the first state.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05KYC1ZMA29H6R9QW36ADRX', '01M05JWBSBWAGG1996DS44GNY8', 'Each press says which way it went, so a board that was already showing everything is distinguishable from one that has just been told to.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05KYDF2N0GXEKQ27585EEP9', '01M05JWBSBWAGG1996DS44GNY8', 'No row in a live state — ready, in progress, blocked or pending — is removed by the filter, with one case per live state rather than one case for the set.', 'must_not', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05KYFJ4SXVNAQ8HBHBH2259', '01M05JWBSBWAGG1996DS44GNY8', 'With the filter widened to hide a live state, the case above fails and names the state it lost — so a filter that removed nothing at all could not pass it.', 'control', 3);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05KYGYV41HV1S6WHYNNS38N', '01M05JWDT6D746WHHMYMX25W99', 'Driving a running board: `ctrl+r` re-reads every project ignoring the cache, `ctrl+f` opens search, `ctrl+g` opens coverage gaps.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05KYJ8TTYCBJA7QXJ445YJ9', '01M05JWDT6D746WHHMYMX25W99', 'No capability the DPM board has and the CPM board lacks is bound to a key that appears in the CPM board''s map, read from that board''s source by the same reader FR1 uses.', 'must_not', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05KYMB19T1Z9XQJ7R6WG1JN', '01M05JWFWE9YFDG4F6TZYEW28Q', 'The strip rendered for the highlighted row carries that row''s own colour blended toward the background — a red row and a green row highlight differently, and neither highlights in a fixed accent colour.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05KYNQ9JBEBT6A0D3TWM361', '01M05JWFWE9YFDG4F6TZYEW28Q', 'Textual''s own highlight style appears on no rendered row, whether or not the list has focus.', 'must_not', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05KYPRMRBER3J02K49J997C', '01M05JWFWE9YFDG4F6TZYEW28Q', 'With the CSS override removed, the criterion above fails — so a board rendering no highlight at all could not satisfy it by having nothing to find.', 'control', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M0D0351EZNM8M7X2024JZ', '01M05JWHYN3X2KS6M596QVZCVW', 'A projects row rendered at column width 24 and again at 48 puts the pill''s last character in the row''s last column both times.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M0ECG46H05E75AP8XAB86', '01M05JWHYN3X2KS6M596QVZCVW', 'The pill and the badge each render in their own colour rather than the row''s status colour, on a row whose status colour differs from both.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M0FT8Z9N3P0KJQYZMNMD9', '01M05JWHYN3X2KS6M596QVZCVW', 'Neither pill nor badge is truncated on a row too narrow to hold everything: the project name is what gives.', 'must_not', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M0HVTB8PGJF3XYRR9Q513', '01M05JWM2TDZDXYM5YP2PBJFQF', 'Source containing a heading, emphasis, a list and a table renders each as a styled construct rather than as its source characters.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M0K8H597XXYB3JBAM9W8K', '01M05JWM2TDZDXYM5YP2PBJFQF', 'The same source rendered at two panel widths breaks its lines differently, so the render is using the panel''s width rather than a default.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M0MKHYQCQN935TT6TKNQW', '01M05JWM2TDZDXYM5YP2PBJFQF', 'Resizing the panel re-renders its contents at the new width.', 'must', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M0NBSG4S7E5GGHZAP44VN', '01M05JWM2TDZDXYM5YP2PBJFQF', 'The panel''s renderable is built from styled text rather than being a live markdown widget, which is what leaves the rendered preview selectable.', 'must', 3);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M0QBPDDCZ726YRX2AS40C', '01M05JWM2TDZDXYM5YP2PBJFQF', 'No markdown marker survives into the rendered output for a construct that was rendered — no `##` before a heading, no `- ` before a list item, no `**` around emphasis.', 'must_not', 4);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M0RQPMEPAX84DSQ8FXGQE', '01M05JWRFR5P502VH5TYJC6RZQ', '`document_preview` returns the document''s title as a markdown heading and each section''s heading as a heading beneath it.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M0T5B77XKPAS8WYNTZV07', '01M05JWRFR5P502VH5TYJC6RZQ', '`story_preview` returns the story''s criteria and tasks as markdown lists, with a task''s description subordinate to the task rather than beside it.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M0W8MRQ84XYWQJP39CYQ2', '01M05JWRFR5P502VH5TYJC6RZQ', 'No plain-text scaffolding label survives in either builder''s output — a bare `Acceptance criteria:` line renders as prose and is the shape this requirement exists to remove.', 'must_not', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M0XJ6YFYWXG5ZKSKXY1JX', '01M05JWTJ2VA95F698PF5AJ2JH', 'The footer shows every bound key, using the CPM board''s wording wherever the action is the same one.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M0Z0QA6MQYH7X9WADF8FE', '01M05JWTJ2VA95F698PF5AJ2JH', 'No footer label or palette entry describes a key that is not bound, and no bound key is missing from the footer — both directions, because either alone is satisfied by a board that documents nothing.', 'must_not', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M30PSYSW62EXFPXNFCHQA', '01M05JWWMC9BJW4624YZVQTR9Q', 'Each of the seven bounded surfaces — bindings, footer, command palette, column layout, row composition, CSS, preview behaviour — has a recorded outcome: a difference closed, a difference recorded as deliberate, or a statement that the surface agrees.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M3226N7HQ5VA84XDQZ2YQ', '01M05JWWMC9BJW4624YZVQTR9Q', 'No surface is left with no outcome recorded. A surface nobody compared reads exactly like one that was compared and agreed, and the record is the only thing that separates them.', 'must_not', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M344AC5JRNP5ZXN5GBPR6', '01M05JWZH4VAJACEP33M4S1P1C', 'Changing a DPM binding so that a key the CPM board binds does something else makes the parity check fail, and the failure names the key.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M35HD86M8RTAP04HB7N2F', '01M05JWZH4VAJACEP33M4S1P1C', 'An unreadable CPM tree makes the check fail rather than skip, and the failure names what it could not read.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M36XGED27VNBRMT27CTM4', '01M05JWZH4VAJACEP33M4S1P1C', 'The check does not assert equality between the two key maps: binding a new DPM-only capability to a key the CPM board does not use leaves it passing.', 'must_not', 2);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M3928744TCJC832843AX8', '01M05K8WX9AVDRMSE0HGKNB8CZ', 'A render for a row the cursor has since left is discarded rather than painted, so moving quickly through a list leaves the panel showing the row the cursor is on.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M39QX12W2Q5H7JP5WBEZM', '01M05K8WX9AVDRMSE0HGKNB8CZ', 'Rendering the largest document in the fixture at 80 columns completes within 50 ms.', 'must', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M3BQXAQN2BTCW60MV5B28', '01M05K8Z0AFQMYF2JCBWNCF1Y7', 'A preview whose source is malformed, pathologically nested, or a single very long line renders something and leaves the board running.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M3CB56G2JNHPEVKFDH1JC', '01M05K8Z0AFQMYF2JCBWNCF1Y7', 'With the guard removed, the same input takes the board down — so the criterion above cannot pass against a renderer that was never at risk from it.', 'control', 1);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M63K8MH49H0XKT5F223TH', '01M05K90WP11SZWPNQZYH6W26C', 'With the console limited to 256 colours, the highlighted row is still distinguishable from an unhighlighted one, and the pill from the row''s own colour.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M650Q5E51V2MB0QJDVN3F', '01M05KAB1GYPQKYV0AT1ZFCB5P', 'pytest and pytest-asyncio are present at or above the stated minimums, and the suite runs from `dpm/tools/board`.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M672ANYWZHJHCZT31BPXB', '01M05KADV6YVN6NAZHT48PRCQH', 'The dependency list in `pyproject.toml` and the PEP 723 inline block in `board.py` name the same packages.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M68FN67ATA370HR6Y6S8N', '01M05KAF6BY0J9X2GN020JK71N', 'The markdown renderer imports, and neither dependency list has gained an entry for it.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M6AK5NC7HN2ZBV37Z79SB', '01M05KAH8JWD17744XDY3S9PTN', 'The CPM board''s source is readable at `cpm/tools/board/` relative to the marketplace checkout root, from the directory the suite runs in.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M6CRPMN9YX9VWQ6Y8G7J0', '01M05KAKAN0ECNYACZGVVBX2QM', 'A socket opened during the suite raises and is recorded, so the run is known to have needed no network rather than assumed to have needed none.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M6E1JAY5KN405Q2CM7DVR', '01M05KAND02WHYZQQRD2C2SFX2', '`board.py` imports nothing outside the standard library and the packages its own inline block declares.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M6G1F50XYYVX9WDMDNG1Z', '01M05KAPS3B31FHN8BYMR70S20', 'The host running the board has Python 3.11 or later, and `uv run` provisions the board from its inline block there.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M6HCJC8G4MT4BJATC5A16', '01M05KARYFQ5C7K2APQ4MPKY35', 'The board starts, paints its columns and answers its keys with no CPM tree anywhere on its path.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05M6K20NPQX397YEDZ5DSGJ', '01M05KATM4Y8TK1NS72EJVGFV9', 'The board renders against a console reporting 256 colours without error, and the render is not silently a monochrome one.', 'must', 0);
INSERT INTO "acceptance_criterion" ("id", "requirement_id", "text", "polarity", "position") VALUES ('01M05MJK5RFYYJCAS1HZHV0QZ9', '01M05MJ4RHTDW90814W6QTH1A3', 'The fixture builds, and holds at least one epic or story in each state the model defines — including `complete`, `superseded` and `withdrawn` — together with a document long enough to time a render against.', 'must', 0);
