INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M05SGVJQ1KHP582CJTJ94WSA', '01M0578Z9Z2AQGTMB8SVN74YR1', 'retro', '01M05NNYYBX6XYRMND1CN4M4TY', 'Read the tree before building; expect the ratio to favour already-there', 'applied', 'Autonomous run: codebase discoveries are additive and low-ambiguity, so this one is applied. It changes Step 1 of every task in this epic — the board already has 36 test files, a tests/support/fixture_database.py and a conftest carrying sandbox, netguard and built_fixture, so each criterion is checked against the tree before anything is written.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M05SGZ49PWBQGVHM20NC7X1K', '01M0578Z9Z2AQGTMB8SVN74YR1', 'retro', '01M05NNYYBX6XYRMND1CN4M4TY', 'A must-NOT stated as an equality is a change detector wearing a rejection''s clothes', 'applied', 'Autonomous run: a pattern worth reusing, so applied. Story 2''s ENVX2 criterion is about the import surface, which is exactly the shape that bit in retro 1 — it is stated over the category (standard library plus the inline block''s own packages, everything else a relative path) rather than as an exact list.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M05SH1W3E1H8HCZ70YEPAR14', '01M0578Z9Z2AQGTMB8SVN74YR1', 'retro', '01M05NNYYBX6XYRMND1CN4M4TY', 'Stubbed tests and a real one are not the same test at different fidelities', 'applied', 'Autonomous run: a pattern worth reusing, so applied. Story 1''s fixture is the thing that makes the real end of that pair possible for this spec — its criteria are tagged integration precisely because a stubbed database would assert the contract and never that the board and the database are connected.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M05SH4N5B35A7R7AK9SBX0FN', '01M0578Z9Z2AQGTMB8SVN74YR1', 'retro', '01M05NNYYBX6XYRMND1CN4M4TY', 'Check a control mutation compiles into the path it is aimed at before believing the red', 'deferred', 'Autonomous run: a testing gap implies a re-planning call that belongs to a human, so it is deferred rather than applied. The same discipline still binds this run through the library document scoped to do, which carries it as standing guidance — this row records that the retro lesson itself was not re-planned against.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M05SH8RV330TMDDS9C2JPZP8', '01M05AXP3B579062HFTK06YJ7J', 'retro', '01M05NNYYBX6XYRMND1CN4M4TY', 'A must-NOT control needs one arm per code path that could reach the rejected behaviour', 'deferred', 'Autonomous run: testing gap, so deferred. It bears on story 1''s must-NOT about where the fixture build writes, which has more than one way to be reached; a human should decide whether that criterion wants a second control arm before the epic is called done.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M05SHATXGBC07WXMTKH8Z6WA', '01M05AXP3B579062HFTK06YJ7J', 'retro', '01M05NNYYBX6XYRMND1CN4M4TY', 'A criterion can read as the natural test of a rule and have no purchase on it', 'deferred', 'Autonomous run: testing gap, so deferred. Named here because story 1''s fixture criterion is of that shape — the fixture building is not the same claim as the fixture holding every state — and a human re-planning it is the sanctioned response.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M05SHDKE8J1RQV3XBY2GDBNV', '01M05AXP3B579062HFTK06YJ7J', 'retro', '01M05NNYYBX6XYRMND1CN4M4TY', 'A criterion warranted by an ADR carries no coverage rows and is invisible to the roll-up', 'deferred', 'Autonomous run: criteria gap, so deferred. It has already recurred in this spec — epic 2 story 5 carries three such criteria, recorded deliberately at breakdown — and the fix it points at is a change to the coverage model, which is nothing this run should decide.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M05YHXWQFKRZ9EDV53E5DK7B', '01M0578Z9Z2AQGTMB8SVN74YR1', 'retro', '01M05NP14C3GCH372FM6NN2T5S', 'Read the tree before building; expect the ratio to favour already-there', 'applied', 'Codebase discovery, applied autonomously. Epic 3 ports a renderer the CPM board already has, so the first move on every task is reading cpm/tools/board/board.py rather than designing one here.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M05YJ0MSCRT9HV8J3DQKEQWD', '01M0578Z9Z2AQGTMB8SVN74YR1', 'retro', '01M05NP14C3GCH372FM6NN2T5S', 'A must-NOT stated as an equality is a change detector wearing a rejection''s clothes', 'applied', 'Pattern worth reusing, applied autonomously. Story 1''s must-NOT is about Textual''s own highlight style appearing on no row; it is written as a rejection over what was rendered rather than an equality against a fixed expected strip.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M05YJ2Q1GEVE3VZ3267GSTCH', '01M0578Z9Z2AQGTMB8SVN74YR1', 'retro', '01M05NP14C3GCH372FM6NN2T5S', 'Stubbed tests and a real one are not the same test at different fidelities', 'applied', 'Pattern worth reusing, applied autonomously. The story''s feature criterion drives a running board through the pilot and reads painted strips; nothing here asserts against a widget''s self-report.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M05YJ657E2FCDTVYZKDPBWRS', '01M0578Z9Z2AQGTMB8SVN74YR1', 'retro', '01M05NP14C3GCH372FM6NN2T5S', 'Check a control mutation compiles into the path it is aimed at before believing the red', 'deferred', 'Testing gap. Deferred unreviewed in autonomous mode: it implies a re-planning call about how controls are written across the epic, which belongs to a human. The control this story already carries is run and read regardless.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M05YJ87GW2WG6QRJFBEJA8DM', '01M05AXP3B579062HFTK06YJ7J', 'retro', '01M05NP14C3GCH372FM6NN2T5S', 'A must-NOT control needs one arm per code path that could reach the rejected behaviour', 'deferred', 'Testing gap. Deferred unreviewed in autonomous mode: widening a control to one arm per path changes what the criteria ask for, which is a human''s call.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M05YJA9NZDV87XBP7ZVG4YES', '01M05AXP3B579062HFTK06YJ7J', 'retro', '01M05NP14C3GCH372FM6NN2T5S', 'A criterion can read as the natural test of a rule and have no purchase on it', 'deferred', 'Criteria gap. Deferred unreviewed in autonomous mode: re-judging whether a criterion has purchase on its rule is a re-planning call.');
INSERT INTO "retro_application" ("id", "retro_id", "retro_kind", "applied_to_id", "theme", "disposition", "note") VALUES ('01M05YJCDWWD7N9653X0EMTCTQ', '01M05AXP3B579062HFTK06YJ7J', 'retro', '01M05NP14C3GCH372FM6NN2T5S', 'A criterion warranted by an ADR carries no coverage rows and is invisible to the roll-up', 'deferred', 'Criteria gap. Deferred unreviewed in autonomous mode: every criterion in epic 3 carries a coverage row, so nothing here is invisible to the roll-up; changing how ADR-warranted criteria are traced is a human''s call.');
INSERT INTO "session" ("id", "skill", "phase", "state", "superseded_by", "created_at", "updated_at") VALUES ('c9d2d7d0-539e-4543-8d15-3722aab48f6f', 'dpm:do', 'Epic 2 complete — spec 1 fully delivered, no ready epics remain', '{"test_command":"npm test (from dpm/)","framework":"node:test","baseline":"809 passing, 0 failing","refactoring":{"e2s1":"none — new migration and new test file, nothing to consolidate","e2s2":"extracted withoutComments() into tests/support/sources.js; hoisted isAbove() into node-floor.js","e2s3":"added previousVersion() to tests/support/migration.js","e2s4":"extracted reshapedStamp(t); removed the unreachable outer catch from stampSkew","e2s5":"new src/server/skew.js holding SKEW, SOURCE, worstState, skewMessage and skewReport; neighbour.js and stamp.js both import it","e2s6":"none — no production code was written","e2s7":"none — one new test file"},"mutations":{"e2s4":"M8 killed; M9 survived then killed after removing an unreachable catch and adding a reshaped-table case","e2s5":"M10 (unconditional stderr) killed by 3; M11 (second top-level field) killed by 1; M12 (roll-up prefers none) killed by 2; M13 (inverted ranking) killed by 4","e2s6":"M14 (read-only branch calls start) killed by 8"},"outstanding":"SERVER_INFO.version is 0.1.0 while package.json is 0.4.0 — left as found, recorded as an observation"}', NULL, '2026-08-16T10:06:51.394Z', '2026-08-16T13:09:12.403Z');
INSERT INTO "session" ("id", "skill", "phase", "state", "superseded_by", "created_at", "updated_at") VALUES ('d5d4f15e-4995-4cd2-84cc-1359f0c4bf1e', 'dpm:do', 'epic 4 complete — retro 4 written, roll-up reported', '{"test_command":"uv run pytest (from dpm/tools/board)","framework":"none (plain Python + Textual)","refactoring":{"epic2-story1":"ran — registry_wiring extracted to tests/support/wiring.py","epic2-story2":"ran — toasts() extracted to pilot.py; show_everything() added","epic2-story3":"ran — surveyed() and registered() moved into wiring.py","epic2-story4":"ran — binding_tuples() extracted in key_maps.py; footer() added to pilot.py","epic2-story5":"ran — disagreement_report() extracted; readable() gates every source read","epic2-story6":"skipped — no implementation task touched code; the story''s whole output is a recorded comparison","epic3-story1":"ran — _painted() extracted in pilot.py so colours() and styles() walk the strips once; suite green after","epic3-story2":"ran — markers() extracted in board_view so the row''s string form and its painted cells share one order and one gap rule; suite green at 302","epic3-story3":"ran — small pass only: the quantisation helpers are this file''s own and the fixtures differ per story; suite green at 305","epic4-story1":"ran — no change warranted: the builders are two short functions with no shared shape worth extracting, and the test file''s headings()/nesting() each ask the parser a different question; suite green at 311","epic4-story2":"ran — the panel''s source and its re-render consolidated onto a PreviewBody widget rather than being split between an app dict and an app-level on_resize; suite green at 319","epic4-story3":"ran — PreviewBody split into show/place/rasterise so the on-loop and off-thread paths share one source-and-content invariant; suite green at 322","epic4-story4":"ran — the raster split into markdown_content (the guard) and _rasterised (the render), which is what gives the control one expression to remove; suite green at 339","epic4-story5":"ran — legend() derived from STATE_STYLE rather than written out, so the palette and its explanation are one table; suite green at 342"}}', NULL, '2026-08-16T14:14:23.386Z', '2026-08-16T20:05:34.724Z');
INSERT INTO "session" ("id", "skill", "phase", "state", "superseded_by", "created_at", "updated_at") VALUES ('d5d4f15e-4995-4cd2-84cc-1359f0c4bf1e-do-e1', 'dpm:do', 'Epic 2, story 2 — Hide retired work', '{"test_command":"uv run pytest, from dpm/tools/board","framework":"none detected (PEP 723 single-file scripts, pytest 8 + pytest-asyncio, asyncio_mode=auto)","retro_gate":{"applied":3,"deferred":4},"epic_1":"complete — 6 of 7 coverage rows verified, the 7th target-only; ENV6, ENV3, ENVX1 claimed whole, ENV1/ENV2/ENVX2 left unclaimed","stories":{"01M05P6A9HYV9QSZJNAP2NB3CY":{"title":"CPM''s key meanings restored","outcome":"complete","refactor":"ran — extracted tests/support/wiring.py from the duplicate registry injections in test_picker.py and test_keys.py; suite green at 267","notes":"r/R/a/x rebound to CPM''s meanings; ctrl+n and ctrl+k dropped; force_refresh unbound until story 3 gives it ctrl+r, so test_cache drives it by action. New tests/support/key_maps.py holds the cross-board reader and a SAME_MEANING table; story 5 builds the check''s own behaviour around it. Parity check watched failing with `x` named."}}}', NULL, '2026-08-16T17:21:26.993Z', '2026-08-16T17:54:16.751Z');
INSERT INTO "session" ("id", "skill", "phase", "state", "superseded_by", "created_at", "updated_at") VALUES ('d5d4f15e-4995-4cd2-84cc-1359f0c4bf1e-quick-1', 'dpm:quick', 'Step 3 — executing: schema, seed, register, tool, registrations, tests', '{"record":"01M0659D8ZXWYSFXE6M8ZM3CM2","path":"change (not fix): the record already exists with its four criteria, written and committed before this run; the resolution was chosen in conversation","resolution":"option 2 — dependency_kind_endpoint, seeded per kind, read by integrity entry 6 and enforced at create_dependency; a kind with no endpoint rows stays unconstrained","test_command":"npm test (from dpm/)"}', NULL, '2026-08-16T20:51:30.026Z', '2026-08-16T20:54:42.214Z');
INSERT INTO "session" ("id", "skill", "phase", "state", "superseded_by", "created_at", "updated_at") VALUES ('d5d4f15e-4995-4cd2-84cc-1359f0c4bf1e-ralph', 'dpm:ralph', 'Epics 3-4 — iteration 2, both epics delivered', '{"harness_session_id":"d5d4f15e-4995-4cd2-84cc-1359f0c4bf1e","note":"The harness session id already keys the dpm:spec/dpm:epics row for this conversation, so this run''s row is keyed on a derived id. The state file carries the harness id — that is what the stop hook matches.","mode":"epic","argument":"epics 3-4","argument_history":["epics 1-4 (launched 17:16Z, worked epics 1 and 2 to completion)","epics 3-4 (relaunched 18:44Z over the two epics still pending)"],"epics":["01M05NP14C3GCH372FM6NN2T5S","01M05NP15VPTJKBNK0B2HQ4XCZ"],"epics_already_complete":["01M05NNYYBX6XYRMND1CN4M4TY","01M05NNZQE4VVEWMCXGMZ72YJ5"],"max_iterations":50,"completion_promise":"ALL_EPICS_COMPLETE","hook":"ralph-loop@ninthspace-ralph 1.2.1, the only enabled Stop hook; ralph-wiggum@claude-code-plugins and ralph-loop@claude-plugins-official are installed and disabled","probe":"dpm 0.5.0 ships no hooks/lib/ralph-hook-probe.sh, so the skill''s named probe could not be run; substituted the plugin''s own tests/test-fail-closed.sh, re-run at this launch — 10/10 including a turn ending on a tool call keeping the loop alive","plan_flags_cleared":["none at this launch: all eight stories across the two epics already carry plan 0"],"gitignore":".claude/ralph-loop.local.md already ignored, line 21","test_command":"uv run pytest (from dpm/tools/board)","launch_commit":"e7f295c","entry_numbering":"entries carry the stop hook''s iteration counter. The counter reset to 1 at the epics 3-4 relaunch, so entries 2 and 3 below belong to the epics 1-4 run and later low numbers belong to this one — the argument_history above is what tells them apart. Entries from the epics 1-4 run count all 16 stories and 47 coverage rows of spec 2; entries from this run count only the 8 stories and 23 rows of epics 3 and 4. Iteration 2 of this run carries two entries: the counter did not advance because the whole of both epics was worked inside it, across two context compactions.","iterations":[{"iteration":2,"counts":{"stories_complete":0,"stories_total":16,"coverage_verified":0,"coverage_total":47},"commit":"b18a6c1","tree":"3b80bd9bf805"},{"iteration":3,"counts":{"stories_complete":2,"stories_total":16,"coverage_verified":6,"coverage_total":47},"commit":"5907a02","tree":"da39a3ee5e6b"},{"iteration":2,"run":"epics 3-4","counts":{"stories_complete":0,"stories_total":8,"coverage_verified":0,"coverage_total":23},"commit":"e7f295c","tree":"da39a3ee5e6b"},{"iteration":2,"run":"epics 3-4","point":"close","counts":{"stories_complete":8,"stories_total":8,"coverage_verified":25,"coverage_total":25},"commit":"90289c5","tree":"da39a3ee5e6b"}]}', NULL, '2026-08-16T17:14:05.037Z', '2026-08-16T20:06:47.736Z');
