INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M054VJMQ0YECK1NNE718SSBM', '01M0578Z9Z2AQGTMB8SVN74YR1', 'retro', '01M052PPSQZFX5YAE75ZZQKBTX', NULL, NULL, 1, 'Three of this story''s four tasks turned out to be already built, and the one criterion that was genuinely unmet belonged to the task that looked most finished.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M054VRSA309TWACBTTJY121X', '01M0578Z9Z2AQGTMB8SVN74YR1', 'retro', '01M052PPSQZFX5YAE75ZZQKBTX', NULL, NULL, 0, 'The control mutation caught a test that was passing for the wrong reason, and it was the test that looked least likely to.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M0558KBV9TM51YE1794EFKXS', '01M0578Z9Z2AQGTMB8SVN74YR1', 'retro', '01M052PRC8AKV31ND1YD9TYMQ8', NULL, NULL, 8, 'This project''s own import sweep reads prose, and a test written to make a structural claim about imports failed it twice for reasons that had nothing to do with imports.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M0558SYN78PY2Q68DE121RNP', '01M0578Z9Z2AQGTMB8SVN74YR1', 'retro', '01M052PRC8AKV31ND1YD9TYMQ8', NULL, NULL, 2, 'Four rejections, four mutations, and one of the four was invalid on its first attempt in exactly the way the library warned about.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M055RM72T5JAMWK9X7Z4WFCV', '01M0578Z9Z2AQGTMB8SVN74YR1', 'retro', '01M052PT0XX69QRRH81SA6WS0B', NULL, NULL, 3, 'A mutation that reversed nothing still passed: replacing "the highest sibling" with "the first sibling above the running version" left every test green, because the fixture''s three directories came back from the filesystem in alphabetical order and that order happened to put 0.10.0 first. The test that was supposed to catch a lexical comparison was passing on an ordering accident rather than on the reduction it was written for. Closing it took a second reading of the same three names through a reader whose order the test chooses. Any assertion over a set the filesystem hands back is an assertion about that filesystem''s ordering unless the ordering is supplied.', '**An assertion over a set the filesystem hands back is an assertion about that filesystem''s ordering.** The fixture''s alphabetical order happened to make "first sibling above" and "highest sibling" the same answer, so the mutation between them passed. The fix — read the same names a second time through a reader whose order the test chooses — is the same seam that made every other claim in this module checkable: the reader is a parameter, and a parameter is what turns "it does one read" and "it takes the highest" from descriptions into measurements.', 'Found by mutation, not by review — five mutations were run against the verdict and this was the only one that survived.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M055S5F7NZ2WM4Z61VB1YQBK', '01M0578Z9Z2AQGTMB8SVN74YR1', 'retro', '01M052PT0XX69QRRH81SA6WS0B', NULL, NULL, 4, 'Story 2''s ENVX4 test asserted the module''s import list by deepEqual against exactly three builtins, and story 3 broke it by importing the version parser from a sibling module — a reuse the spec''s own AD3 called for. The criterion is about what the module can reach outside this process, and an exact-list assertion cannot tell an outbound dependency from a local one. Rewritten to assert over the builtins only, with everything else required to be a relative path inside the project. A must-NOT stated as an equality is a change detector wearing a rejection''s clothes; stating it over the category it is actually about survives the next legitimate change.', '**A must-NOT stated as an equality is a change detector wearing a rejection''s clothes.** Story 2''s "no outbound call" test pinned the import list to exactly three builtins, and story 3 broke it by doing the reuse the spec''s own AD3 asked for. Restating it over the category it is about — which *builtins*, with everything else required to be a relative path — keeps the rejection and survives the next legitimate change. Worth generalising: a rejection asserted by enumeration will fire on the first thing that is fine.', 'The amended test is in tests/neighbour.test.js; the criterion itself was not touched.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M055Y875220Z8Y2G7RXR2MKC', '01M0578Z9Z2AQGTMB8SVN74YR1', 'retro', '01M052PVJ78F729JVQ3374SKS7', NULL, NULL, 5, 'Two things could be cached here and only one of them matters, which the first draft of the entry point got wrong in its own documentation. Hoisting the plugin root to module load is harmless — the running directory is fixed for the process''s whole life, and that pinning is the bug being detected, not a thing that can drift. Hoisting the sibling listing is the actual defect, because the upgrade lands after start. A mutation that hoisted the root failed nothing, which is the correct outcome and was initially read as a gap in the tests; the mutation that memoised the verdict failed all three. Worth stating in general: when a claim is ''do not cache X'', name which X, because an adjacent value that also looks cacheable will absorb the rule and make it untestable.', '**When the rule is "do not cache X", name which X.** Two values here look equally cacheable and only one matters: the plugin root is fixed for the process''s life, the sibling listing is the thing that changes when the upgrade lands. A mutation that hoisted the root failed nothing, and the honest response was to correct the code''s own documentation rather than contrive a test for a non-defect. That is the second of two mutations in this epic whose null result was the right answer — recognising those is as much a part of the discipline as reading the reds.', 'The doc comment on currentSkew was corrected rather than a test being contrived for the non-defect.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M056XFFRG30CZ8T7J25VHJB7', '01M0578Z9Z2AQGTMB8SVN74YR1', 'retro', '01M052PX5CZY0C594F5DZ7DMEQ', NULL, NULL, 6, 'The containment test passed against a deliberately broken implementation, and the reason was the environment rather than the assertion. Written as `currentSkew(throwingReader)`, it resolved the real plugin root — a working tree named for the checkout, not a version — so the check answered could-not-check on the name and never reached the reader at all. It asserted error containment while exercising a short circuit, and would have gone on doing so forever, because the short circuit is the correct behaviour under `--plugin-dir` and nothing about it looks wrong. Naming a version-shaped root instead makes the read actually happen. The general shape: when a function has an early return, a test injecting a fault downstream of it must arrange an input that gets past it, and running the mutation is the only thing that reveals it did not.', '**The worst false pass in the epic, and the story''s own control criterion is what caught it.** A fault injected downstream of an early return never reaches the code it was aimed at — and here the early return is *correct* behaviour (a working-tree root is genuinely uncheckable), so nothing about the test looked wrong. It would have asserted error containment forever while exercising a short circuit. The general rule: when injecting a fault, arrange an input that gets past every guard between the entry point and the injection site, and run the mutation to confirm it did.', 'Found by the story''s own named control criterion — deleting the try/catch and watching what failed.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M056XVQ0FSBN4BXEQV1B16C2', '01M0578Z9Z2AQGTMB8SVN74YR1', 'retro', '01M052PX5CZY0C594F5DZ7DMEQ', NULL, NULL, 9, 'A textual import sweep bit for the second time in this epic, now in src/ rather than tests/. server.test.js scans every source file for the word from followed by a quoted string and reports each hit as an external dependency; a doc comment distinguishing one phrase from another, both quoted, read as an import of a package whose name was a sentence. tests/neighbour.test.js already carried a header note warning the next author, and it was not enough, because the note lives in the file where the trap was previously sprung rather than in the file that does the scanning. The durable fix is either a parser instead of a regex, or a note at the sweep itself — a warning is only read where the reader already is.', '**The warning written after the first occurrence did not prevent the second, because it was written in the wrong file.** `tests/neighbour.test.js` carries a header note about the sweep; the third occurrence was in `src/tools/cross/integrity.js`, whose author had no reason to read it. **This is the epic''s one unactioned finding**, and it is a candidate for either a library entry or a note at the two sweeps themselves — `plugin.test.js:99` and `server.test.js:320`. A warning is only read where the reader already is.', 'Two occurrences now: tests/neighbour.test.js during story 2, src/tools/cross/integrity.js during story 5.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M05733YTA0JWN7EABX7PGZ0H', '01M0578Z9Z2AQGTMB8SVN74YR1', 'retro', '01M052PYQDDQ7DH1QBGNZADESJ', NULL, NULL, 10, 'This record is the first in docs/maintenance/README.md whose "What asserts it" section says nothing does, and saying so plainly was the right move rather than a gap to be filled. Every other entry names a test holding both ends of a coupling. Here the coupling is to a layout the harness owns and the suite deliberately never reads — a test that opened the real plugin cache would pass on the author''s machine for reasons unrelated to the code. So the section states what the suite actually proves (the check reads a layout of this shape, and fails honestly when it cannot) and states that the assumption itself is checked by a person reading the entry. Recording an absence as an absence is what keeps the file''s other entries meaning something; an entry that named a tangentially related test would read as covered.', '**Recording an absence as an absence is what keeps the other records meaning something.** This is the first entry in `docs/maintenance/README.md` whose *What asserts it* says nothing can — because the coupling is to a layout the harness owns and the suite deliberately never reads. Naming a tangentially related test would have read as covered. The same instinct runs through the epic: could-not-check is a distinct state from no-skew, the two shape rejections were left uncovered rather than bound to requirement text that does not support them, and ENV4 has no coverage row because nothing here can produce one.', 'The file''s format was followed otherwise — The record / Why it needs a record / What can break it / What asserts it.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M05760NVXYYXM762ABFPZX36', '01M0578Z9Z2AQGTMB8SVN74YR1', 'retro', '01M052YZWZ5SEB1HYP9VY0TR72', NULL, NULL, 7, 'The cross-story story earned its place, and the mutation that showed it was the cheap one. Wiring the response field to a hardcoded verdict instead of calling the check failed four tests — but two of those four were this story''s, and the other two were story 5''s stubbed tests only because the stub differed from the constant. Every story-5 test injects the verdict, so between them they assert how the report treats a verdict and never once that the check runs. Reading the parent directory instead of the plugin''s own — a resolver bug the unit tests cover thoroughly — failed only the end-to-end test, because it is the only one where the fixture on disk and the code path meet. Stubbed tests and a real one are not the same test at different fidelities: the stub asserts the contract between two parts and the real one asserts the parts are connected, and neither substitutes for the other.', '**The cross-story story earned its place, and it took a mutation to show that too.** Every test in story 5 injects the verdict, so between them they assert how the report treats one and never that the check runs at all. Wiring the field to a constant, and reading the parent directory instead of the plugin''s own, were each caught only where a real fixture on disk meets the real code path. Stubbed and end-to-end tests are not the same test at different fidelities — one asserts a contract between parts, the other asserts the parts are connected — and `dpm:epics` was right to make this a story rather than a task.', 'Both mutations run and reverted from a scratchpad copy; the full suite stands at 768 pass, 0 fail.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M058H2AR2V1PJAGJ33CG0T64', '01M05AXP3B579062HFTK06YJ7J', 'retro', '01M053DWR0V5SD8P9SREMJZP1E', NULL, NULL, 0, 'Adding a table to this schema costs five registrations, not one, and the plan predicted one. The plan said task 2 had "almost nothing to do" because `targetVersion()` derives from the filesystem — true, and beside the point. The full suite then failed in five places, every one a derived sweep doing exactly its job: `parity.test.js`''s `NO_CREATE_TOOL` (a table with no create tool needs a stated exemption), `parity-integration.test.js`''s `UNPROJECTED` twice (once for the reason, once for the closure that holds that set equal to parity''s), `prose-columns.js`''s classification (a new TEXT column needs a judgement), and `schema.test.js`''s primary-key rule.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M058HDKQ7T2DFPK4DAT2XK63', '01M05AXP3B579062HFTK06YJ7J', 'retro', '01M053DWR0V5SD8P9SREMJZP1E', NULL, NULL, 4, 'Criterion 4 — the read-only lockout of older servers — carries no coverage rows, and that is correct rather than a gap. `dpm:epics` refused to bind it because no verbatim fragment of any requirement supports it: it traces to AD2, which accepted the lockout as a deliberate one-time cost, not to a requirement that states it. The same shape appeared twice in epic 1, story 5, where the two AD1-derived shape rejections had no bindable text either.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M058STP6QPGD2523VHWZ1XNB', '01M05AXP3B579062HFTK06YJ7J', 'retro', '01M053DYJ1RV66CC6XZ9ZF89E1', NULL, NULL, 1, 'A must-NOT control found a hole in itself, and only because the mutation was run rather than described. Criterion 3 rejects deriving the version from the containing directory''s name. The test pointed the resolver at `/cache/plugins/dpm/0.3.0` with a manifest saying `9.9.9`, and controlled it with a missing manifest — a reader that throws, against a version-named root, so a directory-name derivation would be the only thing still able to answer `0.3.0`.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M058T2YYCJAK09VHDDC4MXV3', '01M05AXP3B579062HFTK06YJ7J', 'retro', '01M053DYJ1RV66CC6XZ9ZF89E1', NULL, NULL, 10, '`SERVER_INFO.version` in `src/server/mcp.js:32` is `''0.1.0''` while `package.json` says `0.4.0`. It is what the MCP `initialize` handshake answers with, so every client of every dpm release since 0.1.0 has been told the server is 0.1.0. Nothing asserts it — no test in the suite reads `SERVER_INFO.version` — which is why it went stale unnoticed.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M0593T9PBN4PTZNQAGR9ZKK8', '01M05AXP3B579062HFTK06YJ7J', 'retro', '01M053E06Z2GM9R7STNT70P8VM', NULL, NULL, 3, 'The dump criterion does not hold the increase gate, and the story reads as though it does. Criterion 6 — two starts at one version dump identically — is satisfied by a *broken* gate, because an upsert writing the same value produces the same dump. The control mutation (`if (false && …)`, so every start writes) left criteria 6 and 7 both green and was caught only by criterion 3, the one about `written` being false. Criterion 7''s positive half is honest and necessary, and it does not rescue criterion 6: it proves the comparison discriminates *something*, not that it discriminates the gate.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M059435E597YT3CR7ET2X53Q', '01M05AXP3B579062HFTK06YJ7J', 'retro', '01M053E06Z2GM9R7STNT70P8VM', NULL, NULL, 6, 'Task 3 — keep the write off the read-only path — required no code, and the reason is worth recording rather than the fact. `open()`''s read-only branch returns before `start()` is reached, and it opens the connection with `readOnly: true`; the stamp write is refused twice over, by a branch that never calls it and by a connection that would refuse it. That is Epic 48-01''s design paying off in a story written two epics later without anyone having to know about it.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M059MFAGE7ATXV4D3Y40KHKX', '01M05AXP3B579062HFTK06YJ7J', 'retro', '01M053E1Q8TDNDN5B78V98WD47', NULL, NULL, 2, 'A surviving mutation found an unreachable `catch`, and removing it was the right fix rather than contriving a test for it.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M05AER1EQMBZBS3ZC6HZEA7A', '01M05AXP3B579062HFTK06YJ7J', 'retro', '01M053E3BFMFVWFRFCEP2SFYPY', NULL, NULL, 8, 'A shape that was right for one detector had to change when the second arrived, and both changes were forced by criteria rather than chosen.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M05AF5Q7PMSHCJRFGMPW7CTB', '01M05AXP3B579062HFTK06YJ7J', 'retro', '01M053E3BFMFVWFRFCEP2SFYPY', NULL, NULL, 5, 'Fourth criterion in this spec whose must-NOT traces to an ADR rather than to requirement text, and so carries no coverage rows.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M05AMZY67MT06815V5YMAN8M', '01M05AXP3B579062HFTK06YJ7J', 'retro', '01M053E4Z5EW3VZ5FBQ4FNXWB4', NULL, NULL, 7, 'A whole story delivered with no production code, because two earlier decisions had already made it true — and the tests are the only thing that will keep it true.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M05AT30DC9GM3CCBBX6T54EQ', '01M05AXP3B579062HFTK06YJ7J', 'retro', '01M053T5F2BHGEB0A3RBPX8Z8T', NULL, NULL, 9, 'A repeated `start()` rewrites the database file every time while leaving the dump identical, and NFR3''s wording says "byte-identical" about the wrong artefact.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M05T8TSD9D2333GRWJ921PKZ', NULL, NULL, '01M05NTFP3SP5G00T656J93QFX', NULL, NULL, 0, 'The fixture this story was written to build already existed. `tests/support/fixture_database.py` had been carrying a shared project since the board''s own epic 3, complete with `created`, `titles` and `titled` helpers whose docstrings say in as many words that a count written into a test is a transcription that goes stale as the fixture grows. So the story was an extension of a builder rather than a new one: four rows for the two statuses nothing reached, one long document section, and a `statuses` helper alongside the three that were already there. The suite''s baseline also carried a failure nothing in this spec caused — `test_states.py` pointed at `docs/specifications/48-spec-dpm-board.md`, which the CPM-to-dpm migration parked under `docs/cpm/`, so the path was one folder out.', NULL, 'Recorded on the first story of the first epic, which is where the retro lesson about reading the tree first was applied. It paid immediately: the epic was planned from the spec and roughly half of what it named was already in the tree.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M05T8Z9GED7T9AZFSQNDXRS9', NULL, NULL, '01M05NTFP3SP5G00T656J93QFX', NULL, NULL, 1, 'Growing the shared fixture broke two tests, and the interesting one was the test that had already been written not to break. `test_client.py` held a literal `{"complete", "pending"}`, which is the transcription the fixture''s helpers exist to prevent — an easy fix. `test_containment.py` had done the right thing and derived its expected figure from `CONTENT`, and it still broke, because it derived the wrong rule: it counted every story the fixture creates, while `progress` drops a retired story from both sides of the count. Deriving from the source data protects against the fixture growing; it does not protect against the derivation disagreeing with the production rule it is standing in for, and the second failure looks exactly like the board mis-counting.', NULL, 'Both were found by running the suite after the fixture grew, not by reading it. The pattern worth carrying is that a derived expectation needs the rule stated beside it, and the fixture is the place to reach a state that makes the two disagree.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M05TMF6GM6ABKTWKK1R196C2', NULL, NULL, '01M05NTGKBR1C512G581KVZH52', NULL, NULL, 0, 'Task 2''s description said "nothing in the board imports Rich directly today" and `board.py` line 40 reads `from rich.text import Text`. The task was written from the spec, and the spec was written about a renderer nobody had reached for yet; the board had been importing Rich for its own text styling since the TUI landed. This is the second time in one epic that a task planned from the spec described a tree that had moved on — and it cost nothing here only because the task''s own criterion was checkable against the tree rather than against the description.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M05VB5PMXGPNPB3C47PNZQ3R', NULL, NULL, '01M05P6A9HYV9QSZJNAP2NB3CY', NULL, NULL, 0, 'The parity rejection needed a translation table before it could say anything, and that is the finding worth carrying into story 5. The two boards name the same capability differently — `add_project` here is `register` there, `remove_project` is `unregister`, `copy` is `copy_command`, `open_plain` is `open` — so a check comparing raw action names reports four disagreements that are only spellings, and goes on reporting them after somebody fixes the real ones, until nobody reads the output. `tests/support/key_maps.py` therefore carries a `SAME_MEANING` map, and the comparison is over the *intersection* of the two maps rather than an equality between them, which is also what story 5''s own must-NOT asks for.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M05W6FK2MVD1Y01T5YGXCXHZ', NULL, NULL, '01M05P6AZSWD3EZ6JY58YZ1SDG', NULL, NULL, 0, 'Changing a default that seven existing tests had silently baked in cost more than the feature did. The filter itself is two properties and a module tuple; the work was in `test_browser.py` and `test_containment.py`, where fixtures built to exercise "every state" or "the project read whole" now render a subset by default. Every one of those tests was correct and none was about the filter, so the fix was to make each say out loud that it is looking at a board showing everything — a `show_everything(pilot)` helper that presses `z`, rather than reaching into `app.selection`. Two follow-on discoveries: `found()` enumerated the unfiltered `project.epics` to set a cursor index into what is now a filtered column, which was an off-by-n waiting for the first search hit past a complete epic; and a search result landing on a hidden row had to reveal the filter rather than be dropped, since the search reads every epic the project holds and would otherwise offer a row the board then refused to move to. Neither was in the story''s tasks — both came out of asking which callers read the column by index.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M05WFP2YC1XJBF9ECKAYGH2H', NULL, NULL, '01M05P6CEFYY4RZ2KYA6TG1ESC', NULL, NULL, 1, 'A must-NOT over a comparison between two sets needs a floor assertion or it verifies nothing, and the floor has to name the specific things expected in the set rather than assert it is non-empty. "No dpm extra sits on a CPM key" is what an empty extras set says too, and there are several plausible ways for that set to empty itself by accident — the AST reader failing to find CPM''s class, a `SAME_MEANING` entry swallowing a capability CPM does not actually have. Naming `force_refresh`, `search` and `coverage_gaps` and asserting each is being read as an extra is what distinguishes a rejection that holds from one that has stopped looking. The planted control confirmed it: binding `force_refresh` to `z` produced "`z` is this board''s force_refresh and the cpm board binds it to toggle_complete", which names the key and both meanings rather than reporting that two maps differ.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M05WX5TX0KZPV17XK15P68XD', NULL, NULL, '01M05P6D3M5WR5CRXGD2K1M9G6', NULL, NULL, 2, 'Reading the footer from the widgets it built rather than from `BINDINGS` found a bug that had been shipping since the board''s first story: `OptionList` inherits horizontal scroll bindings, and while a column has focus they sit nearer the focused widget than the app''s own, so Textual answered `left` with "Scroll Left" carrying `show=False` and the footer printed neither arrow. Both keys worked — a column that cannot scroll sideways declines its own binding and lets it bubble — so every existing test passed and the only symptom was two undocumented keys. A `Column(OptionList)` subclass re-declaring `left`/`right` against the app''s actions puts the board''s meaning at the near end of the chain, where the footer reads. The general lesson: when a criterion is about what a user *sees*, the artefact to read is the one the framework built, not the table the framework was built from — a comparison between the table and itself reports a footer that never appeared. The same shape would hide a shadowed binding in any Textual app with a focusable scrolling widget.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M05XC7H515DEGQ4KVYWEP70C', NULL, NULL, '01M05PHNRSGHHF8844AHMJ2E7M', NULL, NULL, 3, 'A check that compares this repository against another file has four ways to be green and only one of them is agreement: the second file was never opened, the wrong second file was opened, the comparison cannot fail as written, or the two really do agree. Three of those are only distinguishable by breaking something and reading what comes back, so this story''s tests are mostly plants — an absent tree, a cache-shaped path, a mutated binding, a new capability on a free key. Two things made them worth the effort. First, importing `test_keys`'' own parity test and running it under a substituted `BoardApp.BINDINGS` exercises the assertion that actually runs in the suite, where a re-implementation could satisfy every criterion while the real check had quietly stopped working. Second, the isolation criterion could only be answered in a subprocess from a copied tree: this process has already imported the board from a checkout that does have a cpm tree beside it, so no assertion made in-process can tell a board that never reaches sideways from one that reached and found what it wanted.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M05XG4ERK463RNM6HSYQYSWP', NULL, NULL, '01M05PHPG35ET1G8J5B9AYNHVT', NULL, NULL, 4, '"Recorded as deliberate" turned out to be the outcome that earned this story, and it was the one most at risk of being skipped. Bindings and footer both ended in agreement, which a run could have reported in a sentence; the palette differs on ten of its entries, and the temptation was either to close those differences (making a change nothing in the spec asks for — FR19''s wording clause is scoped to the footer, and the two sets cannot match anyway since dpm has four entries CPM lacks) or to say nothing about them at all. Writing the reason per entry surfaced that one of the differences is forced rather than chosen: "Quit the board" cannot be renamed to CPM''s "Quit" without breaking an existing test, because Textual''s own system command set — the one this board''s provider replaces — already has an entry by that name. A sweep that reported "the palette differs" and moved on would have left that indistinguishable from a difference somebody could close on a slow afternoon.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M05Z65APWAKDP877JMKWXSC8', NULL, NULL, '01M05QK3RW4P1MV94JBZ2MZ5E6', NULL, NULL, 0, 'The CSS override and the render_line repaint look like two ways of doing the same thing, and they are not: the repaint reads the background it blends toward off the strip Textual handed it, so a block cursor left in the stylesheet is not a second highlight underneath the board''s — it is the colour the board''s own highlight gets mixed with. Removing the override paints the blocked row #6c467b (red mixed with Textual''s #0178D4) instead of #760a0a (red mixed with the board''s own #121212). That is what made a real control possible: the naive rejection — "the block cursor colour appears on no rendered row" — passes with the override removed, because the repaint overwrites the background either way. The rejection that has purchase asserts the painted bar is the row''s colour blended toward the surface the *unhighlighted* rows share, and the control fails it by 137 in the blue channel.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M05ZWRBFCG7PCYZS0K5ARFM2', NULL, NULL, '01M05QK55CWG63177HY888NMAG', NULL, NULL, 0, 'A right-justified cell keeps a marker at the edge only while some other cell can give. The badge and the pill with their two-space gaps are 25 cells; the Projects column''s own minimum is 24 — so a row carrying both at that width has already surrendered the whole of its name, and what Rich takes next is the end of the last column, which is the pill. min_width on the marker columns does not save it: it changes the truncation from an ellipsis to a silently dropped session count, which is worse. The floor is recorded in board_view.markers and the rejection is tested at the widths where a layout is actually possible (24 with one marker, 30 and 48 with both), because a criterion asserted at a width where nothing can satisfy it is a criterion that gets edited later rather than met.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M0609XZNE51510NTBSDNTXSX', NULL, NULL, '01M05QK5SX4FZGWHZ9GPZTVXWH', NULL, NULL, 0, 'The failure this story is about was already on the board and invisible from here: a blurred cursor on a dark green (complete) row is #0e2a0e, a legible tint in 24-bit colour, and palette entry 16 — pure black — once a 256-colour terminal quantises it, against a surface at entry 233. Every other state was clear; nothing in the code said which of the seven would collapse, which is the argument for building the fixture from status_model.EPIC_STATES rather than from a sample.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M060HG103SSZ7ZJW21KE5WN8', '01M060H7JNGNZ6SJ8NBC13KVKH', 'retro', NULL, NULL, NULL, 0, 'A rejection is only as good as the thing that would have caught it, and twice in this epic the obvious rejection had no purchase. "Textual''s block cursor appears on no rendered row" passes with the override deleted, because `render_line` overwrites the background either way — what the block cursor actually does is become the colour the board''s own bar is *mixed with*. "No marker is truncated" passes on a board that renders no markers at all. Both were rewritten into a claim about a value someone can compute — the bar is this row''s colour blended toward the surface the unhighlighted rows share; this marker string is present whole — and both then had a control that fails them by a nameable amount.', 'Across all three stories, the criteria that held up were the ones asserting an arithmetic identity rather than an absence. Write the must-NOT as the positive fact whose failure the rejected thing causes, then run the control and read what it says — not merely that it raised.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M060HMVYJC6HJ5KVGP9N0N3Q', '01M060H7JNGNZ6SJ8NBC13KVKH', 'retro', NULL, NULL, NULL, 1, 'Every real failure this epic found was invisible on the machine it was developed on, and each surfaced only because a fixture was built from the model rather than from a sample. The blurred cursor on a `complete` row quantises to pure black at 256 colours — nothing in the code said which of the seven states would collapse, and the fixture that caught it enumerates `status_model.EPIC_STATES`. The pill vanished at 24 cells only when the badge was also present, which a one-marker fixture never reaches. A three-row fixture was needed before "the surface is the commonest background" stopped being decided by paint order.', 'The fixture is where this kind of bug is caught or missed, and enumerating the vocabulary costs nothing at the point of writing. Where a board renders one row per state, render all of them.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M060HSM27K7E46KAEDPMRD5X', '01M060H7JNGNZ6SJ8NBC13KVKH', 'retro', NULL, NULL, NULL, 2, 'Two measurement choices decided whether the checks meant anything. Luminance is the wrong metric for "distinguishable" on a board whose most important row is red — Rec. 709 weights red at a fifth, so a blocked row''s bar reads 2 from the surface by luminance and 77 in the channel a reader sees; the widest single channel is what the tests compare. And the quantisation is Rich''s own `downgrade` rather than a nearest-colour rule written in the test, because a second colour model agrees with the terminal until the day it does not. The same instinct kept `min_width` off the marker columns: it turned a visible ellipsis into a silently dropped session count.', 'Where a test needs a model of something the runtime already models — colour distance, quantisation, layout — call the runtime''s. A parallel model is a second answer that drifts silently.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M060T3850P400MNN6ZG20Y2S', NULL, NULL, '01M05QS8M3SRW6203DQXVBN1G4', NULL, NULL, 0, 'The rewrite was four lines of builder and the whole of the risk was in how it gets checked. Asserting a leading `#` would have been a second markdown parser written in the test file, so both must criteria are read from `rich.markdown.Markdown(source).parsed` — the markdown-it token stream story 2''s panel will actually rasterise. That paid immediately on the nesting criterion: "subordinate to the task" is a claim about the content column the `- ` marker leaves, not about two spaces, and the token''s `level` is the only thing that knows. The old shape (`  {description}`, no marker) is a lazy paragraph continuation and merges into the task''s own inline token, which the level check catches as a missing key rather than as a passing test.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M061DGNTP9Q91CDR5710WB7R', NULL, NULL, '01M05QS9B3SYZE15YZR6T733RD', NULL, NULL, 0, 'The resize criterion nearly passed against a board that re-rendered nothing, and finding that out took a deliberate control. A Textual `Content` re-wraps itself to whatever panel it is in, so "the preview text changed after the resize" is true of a stale raster too — the paragraph reflows either way. What only re-rendering fixes is a construct laid out at the raster''s width rather than wrapped to the panel''s: a heading is *centred*, so a stale one arrives with the old width''s padding still on it and spills onto a second line. That is what the criterion asserts now.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M061RTE258HYYCVS87HZG593', NULL, NULL, '01M05QSAPA8MP912VBFV9M9GEX', NULL, NULL, 0, 'The staleness guard now has to be checked twice, and the second check is the one this story added. The read was already stamped and compared; the raster was not, and it is the wait that grows with the document — so a board that checked only before rendering would spend a whole render on a row the user had left and then paint it over the row they were on. The render also moved off the event loop with `asyncio.to_thread`, which is the codebase''s existing idiom for the tmux poll: a markdown render is arithmetic rather than I/O, so awaiting it on the loop puts every queued keystroke behind it. The width is read on the loop and only the rendering goes to the thread.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M0621ZGR1RRJN0J5GYX0YBKV', NULL, NULL, '01M05QSC2DD8CBEAKHR53440NS', NULL, NULL, 0, 'The story assumed a renderer that could be broken by its input, and it cannot be. Eighteen pathological sources went through the raster before any guard existed — 20,000 nested blockquotes, 2,000 list levels, an unclosed fence, a 100,000-character line, unbalanced brackets, NUL bytes, ANSI escapes, an unpaired surrogate, a 200-column table at ten cells — and every one rendered. Rich and markdown-it treat malformed markdown as text, which is the correct answer and leaves the criterion''s "renders something" asserting that the output is sane rather than that a crash was caught.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M062K1NYRJQYC0KQA5ZRAS2A', NULL, NULL, '01M05QSCJCT9JBH0BQSVQJYCVS', NULL, NULL, 0, 'The sweep found three things, and only one of them was a difference anyone had noticed.
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M062TNT0B08WRGAVPC3GMZPB', '01M062TDTJ5QX1JH6T69J4FEXW', 'retro', NULL, NULL, NULL, 0, 'Two criteria in this epic passed against an implementation that did none of what they claimed, and in both cases the only thing that found it out was deleting the code and watching the test stay green. The resize criterion — "the preview re-renders at the new width" — is satisfied by a stale raster, because a Textual `Content` re-wraps itself to whatever panel it is put in: the paragraph reflows either way, so "the text changed" says nothing. What discriminates is a construct laid out *at the raster''s width* rather than wrapped to the panel''s, and a heading is centred, so a stale one arrives carrying the old width''s padding and spills onto a second line. Story 4''s control was worse than weak, it was unsatisfiable: "the same input takes the board down" cannot be shown, because no input takes it down.', 'Run the control before believing the criterion, and run it by removing the implementation rather than by reasoning about it. A criterion whose control cannot be made to fail is either a claim about something the system does not do or a claim with no observable — and the second one is indistinguishable from a passing test until someone deletes the code.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M062TYGQYX0V012ZKGD2PX9J', '01M062TDTJ5QX1JH6T69J4FEXW', 'retro', NULL, NULL, NULL, 1, 'The epic budgeted a story for surviving bad markdown and found there is no bad markdown. Eighteen pathological sources went through the raster before any guard existed — 20,000 nested blockquotes, 2,000 list levels, an unclosed fence, a 100,000-character line, 5,000 unbalanced brackets, NUL bytes, ANSI escapes, an unpaired surrogate, a 200-column table rendered at ten cells — and every one came back with something paintable, because Rich and markdown-it treat malformed markdown as text. The guard was kept anyway, and the reason is a property of the *path* rather than of the input: the resize render runs on the event loop with nothing catching for it, and eighteen inputs that did not raise is not a proof about the nineteenth. Its fallback is the source itself, so the worst case is a panel showing unrendered markdown.', 'A robustness story is worth checking against the library before it is scoped: the interesting question was never "which input breaks the renderer" but "which caller has nowhere to put an exception". Where the input probe comes back clean, keep the guard on the strength of the path and say in the test file that the inputs proved nothing — otherwise the next reader deletes it as dead weight, correctly reasoning that twelve named sources all rendered.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M062V71Z2266JNG0PY2F5RE8', '01M062TDTJ5QX1JH6T69J4FEXW', 'retro', NULL, NULL, NULL, 2, 'The timing criterion names the fixture''s largest document, and the fixture''s largest document is about 130 characters. It renders in well under a millisecond, so "within 50 ms at 80 columns" was a budget nothing could fail — a criterion that reads as a performance bound and is in fact a bound on the fixture. The test times that document and the same source repeated forty times, which is the size of a real epic doc and the one that could actually blow the budget, and the shortfall is recorded rather than fixed: enlarging a fixture every test in the suite reads would change the ground under three other stories to make one criterion mean what it says.', 'A criterion that quantifies over a shared fixture inherits that fixture''s size, and a fixture kept small on purpose is the wrong thing to quantify over. Where a threshold is about the production shape, name the shape — "a document of N lines" — and let the test build it, so the criterion cannot be satisfied by the test data being small.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M062VE1JBRT4FK9787DVDS2B', '01M062TDTJ5QX1JH6T69J4FEXW', 'retro', NULL, NULL, NULL, 3, 'Three times this epic the right answer was to ask the runtime the question rather than to model it. Story 1''s criteria are read from `rich.markdown.Markdown(source).parsed` — the same markdown-it token stream story 2 rasterises — rather than from a leading `#`, which would have been a second markdown parser living in a test file; that is what caught "subordinate to the task", since a two-space indent with no marker is a lazy paragraph continuation that merges into the parent''s inline token, and only the token''s `level` knows. Story 2''s re-render moved onto the widget''s own `Resize`, which carries the panel''s new size, because the app''s `on_resize` fires before the columns beneath are laid out and rasterises at the width the panel had a moment ago. Story 3''s render went to `asyncio.to_thread`, the idiom the tmux poll already uses, with the width read on the loop and only the arithmetic off it.', 'Where the framework already models the thing under test — a parse, a layout, a size — read its answer instead of writing a parallel one, and prefer the event delivered *to the widget* over the one delivered to the app. The CPM board drives both panels from the app''s resize and gets away with it because its panels are wide and its documents wrap at paragraph level; that is luck holding a design up, not the design being right.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M066BJ1BBFZEJ7P7KYQBS5F0', NULL, NULL, NULL, '01M0659D8ZXWYSFXE6M8ZM3CM2', 'quick', 0, 'A test that derives "the previous version" from the files goes stale exactly as a written number does — three tests about the `plugin_stamp` migration silently became tests about a database that already had the table, and only a migration landing on top of it could ever have revealed that, which is an argument for naming the migration a test is about rather than its distance from the newest one.', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M0Z04X3FH49KH19KBXVTQQX8', NULL, NULL, NULL, '01M0Z04X2W3E7M5T9W6VJRR6KB', 'quick', 0, 'Porting a convention between the two plugins is not a copy, because what a rule costs differs: DPM’s shared file is read once per run so nesting is free, while CPM’s is injected by a SessionStart hook that emits a core section in full, making the choice between `##` and `###` the load-bearing decision — and one that reads as correct prose either way, so only a test over the hook’s output can tell the two apart.', NULL, 'Applies to any future DPM-to-CPM port: check what the CPM hook does with the section before choosing its heading level.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M0Z05YZ67XQWVMB93PJKKBEZ', NULL, NULL, NULL, '01M0Z05YYS3TW9P6GF4D5E29NT', 'quick', 0, 'A trigger that maintains derived state and a trigger that reacts to an edit look identical in the schema and must be treated as opposites by anything that replays rows; the dump had one rule for both, and the only thing that noticed was a round-trip check over real data.', NULL, 'The general shape: any bulk-load path has to ask, per trigger, whether it is rebuilding something absent from the file or responding to an intent nobody had.', NULL, NULL, NULL, NULL);
INSERT INTO "observation" ("id", "retro_id", "retro_kind", "story_id", "quick_id", "quick_kind", "position", "text", "synthesis", "note", "library_doc_id", "library_doc_kind", "retired_at", "retired_reason") VALUES ('01M0Z0GPCR9B1653ESEF88PCRQ', NULL, NULL, NULL, '01M0Z0GPCB1JYVZRWWRC88Z880', 'quick', 0, 'An assertion whose two outcomes produce the same observed value passes forever and reports on nothing; this one guarded the safety property of a rebuild and could not distinguish a refusal from a replacement, because the fixture derived the refused input from the state it was comparing against.', NULL, 'The check that would have caught it is a control asserting the fixture’s two sides actually differ — the same shape retro 30 records for empty-versus-empty comparisons.', NULL, NULL, NULL, NULL);
INSERT INTO "document" ("id", "kind", "numbering", "number", "sequence", "slug", "title", "status", "status_note", "parent_id", "parent_kind", "archived_at", "commit_sha", "created_at", "updated_at", "retro_waived_at", "retro_waived_reason") VALUES ('01M04XXNBGJS968318HYM0WAM8', 'library', 'root', 1, NULL, 'lessons-learned', 'Promoted Retro Lessons', 'complete', 'In force. Each entry names the retro observation it came from; that observation is retired at source, so a lesson lives here or there and never in both.', NULL, NULL, NULL, NULL, '2026-08-16T09:19:53.712Z', '2026-08-16T09:19:53.712Z', NULL, NULL);
