INSERT INTO "story" ("id", "epic_id", "epic_kind", "number", "title", "status", "status_note", "position", "plan") VALUES ('01M05P6CEFYY4RZ2KYA6TG1ESC', '01M05NNZQE4VVEWMCXGMZ72YJ5', 'epic', 3, 'DPM''s extras moved clear', 'complete', NULL, 2, 0);
INSERT INTO "story" ("id", "epic_id", "epic_kind", "number", "title", "status", "status_note", "position", "plan") VALUES ('01M05P6D3M5WR5CRXGD2K1M9G6', '01M05NNZQE4VVEWMCXGMZ72YJ5', 'epic', 4, 'Footer and palette wording', 'complete', NULL, 3, 0);
INSERT INTO "story" ("id", "epic_id", "epic_kind", "number", "title", "status", "status_note", "position", "plan") VALUES ('01M05PHNRSGHHF8844AHMJ2E7M', '01M05NNZQE4VVEWMCXGMZ72YJ5', 'epic', 5, 'The cross-board parity check', 'complete', NULL, 4, 0);
INSERT INTO "story" ("id", "epic_id", "epic_kind", "number", "title", "status", "status_note", "position", "plan") VALUES ('01M05PHPG35ET1G8J5B9AYNHVT', '01M05NNZQE4VVEWMCXGMZ72YJ5', 'epic', 6, 'Sweep the interaction surfaces', 'complete', NULL, 5, 0);
INSERT INTO "story" ("id", "epic_id", "epic_kind", "number", "title", "status", "status_note", "position", "plan") VALUES ('01M05QK3RW4P1MV94JBZ2MZ5E6', '01M05NP14C3GCH372FM6NN2T5S', 'epic', 1, 'The cursor in the row''s own colour', 'complete', NULL, 0, 0);
INSERT INTO "story" ("id", "epic_id", "epic_kind", "number", "title", "status", "status_note", "position", "plan") VALUES ('01M05QK55CWG63177HY888NMAG', '01M05NP14C3GCH372FM6NN2T5S', 'epic', 2, 'The pill against the right edge', 'complete', NULL, 1, 0);
INSERT INTO "story" ("id", "epic_id", "epic_kind", "number", "title", "status", "status_note", "position", "plan") VALUES ('01M05QK5SX4FZGWHZ9GPZTVXWH', '01M05NP14C3GCH372FM6NN2T5S', 'epic', 3, 'Legible without truecolor', 'complete', NULL, 2, 0);
INSERT INTO "story" ("id", "epic_id", "epic_kind", "number", "title", "status", "status_note", "position", "plan") VALUES ('01M05QS8M3SRW6203DQXVBN1G4', '01M05NP15VPTJKBNK0B2HQ4XCZ', 'epic', 1, 'Builders that emit markdown source', 'complete', NULL, 0, 0);
INSERT INTO "story" ("id", "epic_id", "epic_kind", "number", "title", "status", "status_note", "position", "plan") VALUES ('01M05QS9B3SYZE15YZR6T733RD', '01M05NP15VPTJKBNK0B2HQ4XCZ', 'epic', 2, 'Markdown rendered in the preview panel', 'complete', NULL, 1, 0);
INSERT INTO "story" ("id", "epic_id", "epic_kind", "number", "title", "status", "status_note", "position", "plan") VALUES ('01M05QSAPA8MP912VBFV9M9GEX', '01M05NP15VPTJKBNK0B2HQ4XCZ', 'epic', 3, 'The cursor stays ahead of the raster', 'complete', NULL, 2, 0);
INSERT INTO "story" ("id", "epic_id", "epic_kind", "number", "title", "status", "status_note", "position", "plan") VALUES ('01M05QSC2DD8CBEAKHR53440NS', '01M05NP15VPTJKBNK0B2HQ4XCZ', 'epic', 4, 'A preview it cannot render does not take the board down', 'complete', NULL, 3, 0);
INSERT INTO "story" ("id", "epic_id", "epic_kind", "number", "title", "status", "status_note", "position", "plan") VALUES ('01M05QSCJCT9JBH0BQSVQJYCVS', '01M05NP15VPTJKBNK0B2HQ4XCZ', 'epic', 5, 'Sweep the presentation surfaces', 'complete', NULL, 4, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M052XKAJDP0Z00ZHDM3BZ6D1', '01M052PPSQZFX5YAE75ZZQKBTX', 1, 'Build a helper that constructs a temporary directory of sibling version directories', 'The stand-in the neighbour check is pointed at. Addresses the fixture itself, not the check that reads it — and exists so that no test reaches the real plugin cache.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M052XPGK78VXXHZCHXPZ4WRP', '01M052PPSQZFX5YAE75ZZQKBTX', 2, 'Build a helper that creates and removes a temporary location', 'Covers removal on failure as well as on success. A helper that only cleans up on the happy path leaves the next run reading the previous one''s directory.', 'complete', 'The helper already existed as `ownedDirectory` in tests/support/scratch.js, imported by ten test files and tested by none. Nothing was built; the task''s value was discovering that its criterion was unmet and putting the removal under test.', 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M052XR5R340860YK0BZXAMWM', '01M052PPSQZFX5YAE75ZZQKBTX', 3, 'Assert the project''s standing environmental constraints', 'The Node floor matching `engines.node`, and the test script invoking only the built-in runner. Addresses the assertions, not the constraints — both already hold and the point is that they keep holding.', 'complete', 'Both assertions already existed with controls: baseline.test.js:178-188 for the running interpreter against REQUIRED_NODE, server.test.js:92 for engines.node, baseline.test.js:154-174 for the runner and the absence of an install step. Verified and cited rather than duplicated — devDependencies is already asserted empty in four files.', 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M052XTBHFGQEJWT07ZPT1BV9', '01M052PPSQZFX5YAE75ZZQKBTX', 4, 'Write tests for the scaffolding helpers', 'Covers the four criteria tagged `unit`. The helpers are themselves test machinery, so they need cover of their own — a fixture builder that silently builds nothing would make every test above it pass for the wrong reason.', 'complete', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M052XZ5FQJV46W24VBPP959V', '01M052PRC8AKV31ND1YD9TYMQ8', 1, 'Resolve the running plugin''s directory from the module''s own URL', 'Takes nothing from the process environment. Respects the decision that the host expands its plugin-root placeholder into launch arguments and does not guarantee it as a variable.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M052Y0SB9AB3MC61HMK2Y76Q', '01M052PRC8AKV31ND1YD9TYMQ8', 2, 'Read the sibling directories, taking the root and the reader as parameters', 'One read, no recursion, nothing written. The reader is a parameter so the read can be counted and so the path read is the path given — which is what makes the bounded-cost and no-home-directory criteria checkable at all.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M052Y2EDEMTYGMMY3C9F5B3D', '01M052PRC8AKV31ND1YD9TYMQ8', 3, 'Write tests for resolving the version and its neighbours', 'Covers the ten criteria tagged `unit` and `integration`, including the four rejections — recursion, process or socket, any write, and any path through the home directory.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M052Y44WCN6R5RMBHMWZFHZD', '01M052PT0XX69QRRH81SA6WS0B', 1, 'Compare sibling names as versions using the existing parser', 'Addresses the direction of the comparison and the unparseable path. Reuses the parser the Node floor check already carries rather than adding a dependency for it.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M052Y5SPEDM1Q77H38X3MAK8', '01M052PT0XX69QRRH81SA6WS0B', 2, 'Define the three-state verdict', 'Skew found, no skew, could not check — distinguishable from the value rather than from its message text, so that a reader branching on the state never has to parse prose.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M052Y7VNN3ZHS7BFKNPYDPPB', '01M052PT0XX69QRRH81SA6WS0B', 3, 'Write tests for the comparison and the verdict', 'Covers the nine criteria tagged `unit`, including the rejection of a skew reported for a lower sibling — the case a reversed comparison would otherwise pass.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M052YAT5VW2RPK18FFM7XTM0', '01M052PVJ78F729JVQ3374SKS7', 1, 'Evaluate the check at report time rather than at start', 'Addresses the wiring, not the check. Nothing computed at module load or server start may be reused, because the upgrade this exists to catch lands after both.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M052YCP0CRVXQ04EMZG5RQB5', '01M052PVJ78F729JVQ3374SKS7', 2, 'Write tests for re-evaluation on every report', 'Covers both criteria tagged `integration`. The control is run rather than reasoned about: memoise the check, watch the two-report test fail, and read why before reverting.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M052YJXC6A7S699M6M9APEV6', '01M052PX5CZY0C594F5DZ7DMEQ', 1, 'Add the skew field to the integrity response', 'Beside `entries` and `orphans`, never inside either. Respects the decision that `ok` keeps meaning the data is sound and that the entries list stays derived from the register.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M052YMWY0QDAZF3NYKEBHY0J', '01M052PX5CZY0C594F5DZ7DMEQ', 2, 'Compose the skew sentence in one place', 'One producer, used by every channel that reports a skew. Addresses the wording, not the detection — two channels and two detectors is four chances for the sentence to be written four times and drift.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M052YPCCA2CCVXK0FK2PD6Z9', '01M052PX5CZY0C594F5DZ7DMEQ', 3, 'Contain failures inside the check', 'Addresses the error path, not the happy path. A read that throws becomes could-not-check and a successful response; nothing from the check reaches the caller as an error.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M052YRHE54YTYTKRGT773907', '01M052PX5CZY0C594F5DZ7DMEQ', 4, 'Write tests for reporting the verdict on check_integrity', 'Covers the eight criteria, including the two rejections that hold the report''s shape and the control on error handling — which is run and its failure read, not assumed.', 'complete', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M052YW7CW4BKMCTSK2P1M0N9', '01M052PYQDDQ7DH1QBGNZADESJ', 1, 'Write the maintenance record for the plugin-cache coupling', 'What layout is assumed, and what breaks if the host changes it. The coupling is to something we do not own, so the record is the only place it is stated deliberately rather than implied by code.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M052YYA7RCGB0NRPW98ZRZ5Z', '01M052PYQDDQ7DH1QBGNZADESJ', 2, 'Write the test that no skill file names the maintenance record''s path', 'Covers the criterion tagged `unit`. The record''s content is judged by reading it; what a test can hold is that no skill pays for a pointer to it on every invocation.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M052Z8Y6VZEE1AQ17N8ZMVP9', '01M052YZWZ5SEB1HYP9VY0TR72', 1, 'Write the end-to-end tests for neighbour skew reporting', 'A real tool call against a real constructed cache, covering the whole path the per-story tests only cover a link of. Both criteria name the state of `ok`, which is what shows the report''s separation holding end to end rather than only in the unit test written against the same assumption.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M053Q7VHW3F3TWRPX6KNEZT2', '01M053DWR0V5SD8P9SREMJZP1E', 1, 'Write the migration adding the one-row stamp table', 'The DDL and the constraint that admits only one row. Addresses the table''s existence and shape, not the write path — the migration inserts nothing.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M053Q9RXD8YPDQH8KDFRYFHP', '01M053DWR0V5SD8P9SREMJZP1E', 2, 'Raise the schema target version and register the migration', 'Addresses the ordered migration list and the version the server reports as its target. This is the change that puts older servers into the read-only branch, which AD2 accepted.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M053QC54GXFT03BAF0ZBPF8J', '01M053DWR0V5SD8P9SREMJZP1E', 3, 'Write tests for The stamp table and its migration', 'Covers the six criteria tagged integration, including the second-row rejection and the assertion that an older server degrades to read-only rather than failing.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M053QERVMPK1AJ6EP3WW2YQV', '01M053DYJ1RV66CC6XZ9ZF89E1', 1, 'Add a resolver reading the version from the plugin''s own manifest', 'Addresses the case the neighbour check cannot serve — a plugin loaded from a working tree, where no version directory exists to read a name off.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M053QGK5F5VAJ0NWA9TFMY64', '01M053DYJ1RV66CC6XZ9ZF89E1', 2, 'Write tests for Resolve this server''s own plugin version', 'Covers the four criteria tagged unit, including the two rejections: no directory-name derivation and no read of process.env.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M053QM1M27MHNMTC3JJTMY6A', '01M053E06Z2GM9R7STNT70P8VM', 1, 'Add the stamp write as a fourth step in start()', 'Addresses where the write sits in the fixed order: after migrate, because the table it writes to is created there. Scope is placement, not the increase condition.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M053QNNBHGNAP2THGKYEY35C', '01M053E06Z2GM9R7STNT70P8VM', 2, 'Gate the write on the running version exceeding the recorded one', 'Addresses FR2a — equal and lower both leave the row untouched, so the stamp never moves backwards and an unchanged project produces an unchanged dump.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M053QQAWHHHDWQZ992XRS2VW', '01M053E06Z2GM9R7STNT70P8VM', 3, 'Keep the write off the read-only path', 'A separate path from the increase gate: a correct gate still writes when a newer server merely observes a project. Addresses the read-only rejection only.', 'complete', 'Required no code: `open()`''s read-only branch returns before `start()` is reached, and the connection is opened read-only, so the write is refused twice over. The task''s work was the assertion and its control.', 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M053QRZTYW68600EMJX3N84M', '01M053E06Z2GM9R7STNT70P8VM', 4, 'Write tests for Write the stamp on increase', 'Covers the ten criteria tagged integration, including both dump comparisons and the control that makes the write unconditional and observes the untouched-row criterion fail.', 'complete', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M053QV6AYMQ5DR2RENFQ0NFR', '01M053E1Q8TDNDN5B78V98WD47', 1, 'Read the recorded stamp, tolerating an absent table', 'Addresses the read and its failure mode. An absent table is the ordinary case for a project this release has never opened, so it is a value the reader returns rather than an error it raises.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M053QWYBGQQ7CHBGP3JW516Y', '01M053E1Q8TDNDN5B78V98WD47', 2, 'Compare with the running version and return the three-state verdict', 'Addresses the comparison and its three outcomes, reusing parseVersion. Scope is the verdict; how it is reported belongs to story 5.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M053QYNY79Q7XK2JHW9KJN2H', '01M053E1Q8TDNDN5B78V98WD47', 3, 'Write tests for Compare the stamp and produce a verdict', 'Covers the five criteria tagged integration, including the rejection that an absent or unreadable stamp must not render as no-skew.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M053R0T5EXQW2ND2TQ9AC6QD', '01M053E3BFMFVWFRFCEP2SFYPY', 1, 'Extend the single skew composer to cover the stamp skew', 'Addresses the sentence, not its transport. FR4 requires one composer, so this extends what epic 1 built rather than adding a second one.', 'complete', 'The composer moved to a new src/server/skew.js along with the SKEW vocabulary and a new SOURCE discriminator, rather than being extended in place: neighbour.js was the right home while it was the only detector, and a module named for the plugin cache composing a sentence about the database is one nobody would look in. Both detectors now tag their verdicts with their source, and the composer selects its sentence table from that.', 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M053R2MMKT9YWYYNYJRWM3CT', '01M053E3BFMFVWFRFCEP2SFYPY', 2, 'Report the stamp skew through the field the neighbour skew already uses', 'Addresses the tool response. AD1 gave the skew one top-level field beside entries and orphans; this fills it from a second source rather than adding a field.', 'complete', 'The one field now holds both verdicts under their source names, with a rolled-up state and message above them. Epic 1''s flat shape assumed one detector; keeping it would have meant a second top-level field, which is the story''s own must-NOT. Six assertions in cross-tools.test.js moved from report.skew.* to report.skew.neighbour.* — a relocation, with their substance unchanged.', 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M053R4TXY65DW58RXFWRT79H', '01M053E3BFMFVWFRFCEP2SFYPY', 3, 'Write the stderr line at database open', 'Addresses FR6 and the parity with the existing ahead-message. A clean open stays silent, which is what makes a line that does appear worth reading.', 'complete', 'Only `found` writes a line. `none` is the ordinary case and would be noise on every open; `unknown` is the ordinary case for a project this release has never migrated, and a warning nobody can act on trains a reader to skip the ones they can. Both still reach check_integrity, where a caller asked for them.', 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M053R6ZNT9HM0R049WFTXMSV', '01M053E3BFMFVWFRFCEP2SFYPY', 4, 'Write tests for Report the stamp skew on check_integrity and stderr', 'Covers the five criteria tagged integration, including the silence of a clean open and the rejection of a second top-level field.', 'complete', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M053R95F6BD03XE1NTDM48QW', '01M053E4Z5EW3VZ5FBQ4FNXWB4', 1, 'Reach both detectors from the read-only branch of open()', 'Addresses the path that never calls start(). Both detectors have to be reachable without it, and neither may write anything on the way.', 'complete', 'No code was needed, and the reason is worth keeping. Both detectors are defaults on `spineTools`, which the read-only branch already calls; `check_integrity` declares `mutates: false`, so `readOnlyTools` leaves its handler alone. A read-only launch against a database stamped at 99.0.0 was verified to report `skew.stamp.state: found` with the neighbour half beside it, unchanged. Writing a second wiring here would have been a second answer to a question the tool table already answers, and the two would have disagreed the first time either moved. Story 5''s `skewReport` extraction, made in anticipation of a second construction site, turns out not to be needed for that reason — it stays because it is where the shape belongs, not because two callers build it.', 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M053RASNZEGX4AYAKD06FJQ9', '01M053E4Z5EW3VZ5FBQ4FNXWB4', 2, 'Write tests for Report both skews under a read-only launch', 'Covers the three criteria tagged integration, including the rejection that a read-only launch writes nothing while reporting a skew.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M053TTJ84H73WSFQGTZE758F', '01M053T5F2BHGEB0A3RBPX8Z8T', 1, 'Write the cross-story integration tests for the database stamp', 'Covers behaviour spanning stories 1 to 6 — the end-to-end skew and the dump left undisturbed by both detectors together. Not a repeat of the per-story suites.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05NW7RBKAE2ZHFW28SF1SXW', '01M05NTFP3SP5G00T656J93QFX', 1, 'Seed every state into the fixture builder', 'Addresses the state-coverage half of the story''s first criterion. The states are taken from the model''s own vocabulary rather than a list written here, so a state added to the model later appears in the fixture without this task being revisited.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05NWAFJXVYGNNRNHTRX1SEV', '01M05NTFP3SP5G00T656J93QFX', 2, 'Add a document long enough to time a render against', 'Addresses the second half of the same criterion, and is what NFR1''s 50 ms budget is measured on. Long enough that changing the render width changes the line breaks, since a document that fits on one line at any width measures nothing.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05NWCH1564S32ZHWSPPXS8C', '01M05NTFP3SP5G00T656J93QFX', 3, 'Write tests for the fixture', 'Covers both criteria tagged `integration`, including the must-NOT on where the build writes — which needs a sandbox the test owns and an assertion about what appeared in it, not merely that the expected file appeared.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05NWFANRNEXMPGHGN2BKZ16', '01M05NTGKBR1C512G581KVZH52', 1, 'Assert the runner, the dependency agreement and the import surface', 'Addresses the four claims expected to hold already: the pytest and pytest-asyncio minimums, the agreement between `pyproject.toml` and the inline block, the network guard, and `board.py`''s import surface. Expect these to pass on the first run; the value is that they keep holding.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05NWHAGEPXC6QGKK645Z99H', '01M05NTGKBR1C512G581KVZH52', 2, 'Assert the markdown renderer imports with no new dependency', 'Addresses the renderer criterion only, and is the one claim in this story not already true — nothing in the board imports Rich directly today. The assertion has two halves: the import succeeds, and neither dependency list gained an entry for it.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05NWK2BHJ4E6PNFCZNQ6JMX', '01M05NTGKBR1C512G581KVZH52', 3, 'State the host''s Python floor and why it cannot be checked here', 'Addresses the `target` criterion. Records the condition and what would settle it rather than self-assessing it on a machine that satisfies it — confirming a version floor where the floor is met is the false pass `target` exists to stop.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05Q9K5WR5J5DFDXQRHV01TS', '01M05P6A9HYV9QSZJNAP2NB3CY', 1, 'Rebind r, R, a and x to CPM''s meanings', 'Addresses the first two criteria. `R` takes clear-cache back from the forced re-read, which moves in story 3; `r` and `x` are new bindings rather than moved ones, because refresh and unregister exist on this board today as palette entries with no key.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05Q9NDF14BHCES5PTWCA1DP', '01M05P6A9HYV9QSZJNAP2NB3CY', 2, 'Write tests for CPM''s key meanings restored', 'Covers the criteria tagged `feature` and `integration`. The rejection is the cross-board one, so it uses story 5''s reader — which means this task lands its full weight only once story 5 exists.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05Q9R25QF2691Q1ZWA9MCCX', '01M05P6AZSWD3EZ6JY58YZ1SDG', 1, 'Add the retired filter over the model''s own grouping', 'Reads `status_model.RETIRED` plus `complete` rather than restating `superseded` and `withdrawn` where the board can drift from the model. Addresses the filter, not the key.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05Q9T2E63QDQWA8XA3KV7JZ', '01M05P6AZSWD3EZ6JY58YZ1SDG', 2, 'Bind z, open hidden, and report each press', 'Addresses the toggle and the notification. Opening hidden is the CPM default and means this board shows fewer rows on first run than it does today — expected, not a regression.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05Q9W5K7GN7Q00ANSTMM2KX', '01M05P6AZSWD3EZ6JY58YZ1SDG', 3, 'Write tests for hide retired work', 'Covers all four criteria, including the control that widens the filter to hide a live state — without it, the must-NOT passes equally against a toggle that hides nothing at all.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05Q9Z8C23CSX33YYY0QJGC0', '01M05P6CEFYY4RZ2KYA6TG1ESC', 1, 'Move the forced re-read to ctrl+r', 'Frees `R` for story 1''s clear-cache and leaves `ctrl+k` unused. Search and gaps keep the keys they have; this task is only the eviction.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05QA0B2CRK7CSPWRNMJ49C5', '01M05P6CEFYY4RZ2KYA6TG1ESC', 2, 'Write tests for DPM''s extras', 'Covers the three extra keys driven through a running board, and the rejection read from CPM''s map by story 5''s reader.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05QA3381HABSS2BE5DM3XFB', '01M05P6D3M5WR5CRXGD2K1M9G6', 1, 'Align the footer labels with CPM''s wording', 'Only where the action is the same one — DPM-only capabilities keep their own labels, having nothing on the other board to match.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05QA55DWNWP12FXFZWNA31A', '01M05P6D3M5WR5CRXGD2K1M9G6', 2, 'Update the palette entries for actions that now have keys', 'Refresh and unregister gained keys in story 1, so their palette entries now describe a capability reachable two ways. Addresses the palette half of the must-NOT.', 'complete', 'No entry needed rewording. Every palette help string was checked against the keys stories 1 and 3 added: none names a key, none claims a capability is palette-only, and every entry''s action resolves to a method on the app. The obligation now sits in a test rather than in prose — `test_nothing_is_documented_that_no_key_or_entry_reaches` fails if a palette entry ever starts describing something nothing reaches.', 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05QA6M8WNSN4RKWMRE301N6', '01M05P6D3M5WR5CRXGD2K1M9G6', 3, 'Write tests for footer and palette wording', 'Covers both directions of the must-NOT — no label for an unbound key, and no bound key without a label. Either alone is satisfied by a board that documents nothing.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05QA99YRT0T35V39H6VM2YT', '01M05PHNRSGHHF8844AHMJ2E7M', 1, 'Write the reader that extracts a key map from a board''s source', 'One reader, run against both boards, and the thing stories 1 and 3 lean on for their rejections. It reads the repository source rather than the installed plugin cache.', 'complete', 'Written in story 1 as `tests/support/key_maps.py` and finished here: `binding_tuples` now gates every read through `readable`, which refuses a path under an installed plugin cache before opening it and asserts — naming the path — when the tree is absent.', 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05QABC00G7AJMHXQFTKQQAG', '01M05PHNRSGHHF8844AHMJ2E7M', 2, 'Write the check as a category claim over CPM''s map', 'Every key CPM binds means the same here; DPM''s extras touch nothing in that set. Addresses the must-NOT that this is not an equality — a whole-map comparison fires the first time either board legitimately grows a key.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05QAE5H8W9CMB3TX90BQAE6', '01M05PHNRSGHHF8844AHMJ2E7M', 3, 'Run the mutation and the unreadable-tree case, and read what each failure says', 'An activity rather than an artefact, and deliberately so: the failure has to name the key, or the tree it could not read, rather than merely being red. A mutation that fails for the wrong reason is not yet a control.', 'complete', 'Both cases run, and both read for what they said rather than for red. The mutation put `quit` on `x` — CPM''s unregister — and the check answered "`x` is remove_project on the cpm board and quit here". The absent tree answered with the path it wanted and the reason a skip would be wrong. The activity is now also a standing test in `tests/test_parity.py`, so neither case depends on having been run once by hand.', 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05QAG86576XMZBYF2KRWKSD', '01M05PHNRSGHHF8844AHMJ2E7M', 4, 'Assert the board runs with no CPM tree present', 'The production restriction, checked here because the environment is reproducible: a board launched from a copy with no sibling starts, paints and answers keys. Keeps the sideways reach in the suite and out of the board.', 'complete', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05QAJPHV6WHFTSYSGQKC1JZ', '01M05PHPG35ET1G8J5B9AYNHVT', 1, 'Compare bindings, footer and palette, and record an outcome for each', 'Three surfaces, three outcomes: a difference closed, a difference recorded as deliberate, or a statement that the surface agrees. A surface with no outcome recorded is the failure this story exists to prevent.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05QND4NDSPA598SDG2VEZ4D', '01M05QK3RW4P1MV94JBZ2MZ5E6', 1, 'Port InverseOptionList from the CPM board', 'The render_line override that repaints the highlighted strip in the row''s own colour, blended toward the background. Addresses the cursor''s appearance only — the row''s content composition belongs to story 2.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05QNF7JJBH61AK0JDKZSK16', '01M05QK3RW4P1MV94JBZ2MZ5E6', 2, 'Neutralise Textual''s highlight style in the board''s CSS', 'Addresses the default highlight block showing through the repainted strip, which the render_line override alone does not stop. It is the thing the story''s control criterion removes.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05QNH9G7AF9C14HJVMMB6FV', '01M05QK3RW4P1MV94JBZ2MZ5E6', 3, 'Write tests for The cursor in the row''s own colour', 'Covers the four criteria: the three tagged unit, including the control — which has to fail with the CSS override removed, so that a board rendering no highlight at all cannot satisfy the rejection by having nothing to find — and the one tagged feature, which drives a running board rather than the render function.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05QNKBN972J40Y8AZ9YDV8R', '01M05QK55CWG63177HY888NMAG', 1, 'Compose the projects row as a grid with a right-justified pill cell', 'Replaces the string suffix the DPM board appends today. Addresses placement only; the colours the pill and badge carry are the next task.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05QNNPZ5Y3TZR2GJRDKNBZE', '01M05QK55CWG63177HY888NMAG', 2, 'Give the pill and the integrity badge their own styles over the row''s status colour', 'Addresses colour independence from the row. The badge is a DPM capability with no CPM counterpart to copy, so its style is decided here rather than ported.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05QNPT6PFATF081FAVK0ZM5', '01M05QK55CWG63177HY888NMAG', 3, 'Make the row composition follow the projects column''s width', 'Addresses width-independence at any column width, not only the two the criterion names, and the re-render when that width changes.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05QNRXRTTMNVVWS4840JJ07', '01M05QK55CWG63177HY888NMAG', 4, 'Write tests for The pill against the right edge', 'Covers the three criteria tagged unit — placement at two column widths, the colours over a differing row colour, and the rejection that what gives on a narrow row is the project name.', 'complete', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05QNVQ5P64M4F7H9S4GM8E5', '01M05QK5SX4FZGWHZ9GPZTVXWH', 1, 'Choose blend and pill colours that survive a 256-colour downgrade', 'Addresses the palette values rather than the render path, which stories 1 and 2 deliver. What is at stake is that the blend and the pill remain distinguishable once the terminal has quantised them.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05QNWZEQZWTYYFJX8YZZXG6', '01M05QK5SX4FZGWHZ9GPZTVXWH', 2, 'Write tests for Legible without truecolor', 'Covers the two criteria tagged unit, driving the render against a console that reports 256 colours rather than truecolor.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05R2G2PDC4DV22G8R76ZVW6', '01M05QS8M3SRW6203DQXVBN1G4', 1, 'Rewrite document_preview to emit markdown', 'The document''s title as a heading and each section''s heading as a heading beneath it. Addresses the source the builder returns; how the panel renders it is story 2.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05R2J58319J9E2FXB4R7VHW', '01M05QS8M3SRW6203DQXVBN1G4', 2, 'Rewrite story_preview to emit markdown', 'Criteria and tasks as markdown lists, with a task''s description subordinate to its task rather than beside it. The plain-text scaffolding labels go here, not somewhere else.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05R2KQB1RT57VVD018YDQK1', '01M05QS8M3SRW6203DQXVBN1G4', 3, 'Write tests for Builders that emit markdown source', 'Covers the three criteria tagged unit. The existing tests/test_previews.py pins the plain-text shapes these builders no longer produce, so its assertions move with them rather than being left to fail.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05R2P9NH83Y7RB9MYDHGHKE', '01M05QS9B3SYZE15YZR6T733RD', 1, 'Port markdown_content and HardBreakMarkdown from the CPM board', 'Rasterise markdown through a Console at a given width and rebuild the segments into styled text. The rebuild is the part that matters: it is what leaves the rendered preview selectable, which a live markdown widget does not.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05R2RBTT46ZA3SG6FWBPQ7T', '01M05QS9B3SYZE15YZR6T733RD', 2, 'Feed the preview panel the rasterised renderable instead of a plain string', 'Addresses the panel''s content only. The builders that supply the source it rasterises are story 1.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05R2TDV40TDYCYG8HRT7PP8', '01M05QS9B3SYZE15YZR6T733RD', 3, 'Re-render the preview at the panel''s new width on resize', 'Addresses the raster being width-specific: a resize invalidates it, and a panel left holding the old raster shows lines broken for a width it no longer has.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05R2VWATQ5BFVH4TK0GK424', '01M05QS9B3SYZE15YZR6T733RD', 4, 'Write tests for Markdown rendered in the preview panel', 'Covers the five criteria — four tagged unit, and the resize one tagged feature, which drives the board rather than the render function.', 'complete', NULL, 3);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05R2XWC7FG6YKJCCYYSWXJ5', '01M05QSAPA8MP912VBFV9M9GEX', 1, 'Discard a render whose row is no longer the highlighted one', 'Addresses the stale paint — a panel showing a row the cursor has left — rather than the cost of the render itself, which is the next task.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05R2ZYKB1ERMB2MSSV28728', '01M05QSAPA8MP912VBFV9M9GEX', 2, 'Keep the raster off the key-handling path', 'Addresses a held arrow key queueing one render per row passed over, and key handling blocking while a render runs.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05R322VMQGZ40KTGPQPV7S5', '01M05QSAPA8MP912VBFV9M9GEX', 3, 'Write tests for The cursor stays ahead of the raster', 'Covers the feature criterion on fast cursor movement and the unit criterion holding the render of the fixture''s largest document at 80 columns within 50 ms.', 'complete', NULL, 2);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05R345TK4YQ9J6TGPT3ZMX7', '01M05QSC2DD8CBEAKHR53440NS', 1, 'Guard the preview render so a source it cannot handle yields something renderable', 'Covers malformed markdown, pathological nesting and a body that is one very long line. This guard is the thing the story''s control criterion removes.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05R364XFZJK64WF36R20ZKH', '01M05QSC2DD8CBEAKHR53440NS', 2, 'Write tests for A preview it cannot render does not take the board down', 'Covers both criteria tagged unit, including the control — which has to fail with the guard removed, so the rejection cannot pass against a renderer that was never at risk from the input.', 'complete', NULL, 1);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05R3896YHDRXMBDGM69RV97', '01M05QSCJCT9JBH0BQSVQJYCVS', 1, 'Compare column layout and row composition across the two boards', 'Each surface gets a recorded outcome: a difference closed, a difference recorded as deliberate, or a statement that the surface agrees. Reads the repository source of both boards, never the plugin cache.', 'complete', NULL, 0);
INSERT INTO "task" ("id", "story_id", "number", "title", "description", "status", "status_note", "position") VALUES ('01M05R3AB4XY9REDEGJEQH87S6', '01M05QSCJCT9JBH0BQSVQJYCVS', 2, 'Compare CSS and preview behaviour across the two boards', 'The same three outcomes, over the two surfaces this epic has just moved. A difference introduced by stories 1 to 4 and left unrecorded is the case this task exists to catch.', 'complete', NULL, 1);
INSERT INTO "document_agent" ("document_id", "document_kind", "agent") VALUES ('01M05HXF3GS1DSX68YSBR6M0C8', 'discussion', 'dev');
